          <button
            type="button"
            {...tapMissed}
            disabled={generating}
            className="rounded-xl border border-rose-200 bg-rose-50 px-4 py-2.5 text-sm font-semibold text-rose-700 hover:bg-rose-100 disabled:opacity-60 touch-manipulation"
          >
