"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Loader2, Play } from "lucide-react";

import { saveStudySession } from "@/components/study/StudySessionRunner";
import { StudyLoopStrip } from "@/components/study/StudyLoopStrip";
import type { MixedReviewStep } from "@/lib/csl/mixed-review";
import { resolveLoopFocusTopic } from "@/lib/study/resolve-loop-focus-topic";

export function MixedReviewView() {
  const searchParams = useSearchParams();
  const queryCourseId = searchParams.get("courseId")?.trim() || "";
  const urlTopic = searchParams.get("topic")?.trim() || null;
  const [loading, setLoading] = useState(true);
  const [steps, setSteps] = useState<MixedReviewStep[]>([]);
  const [summary, setSummary] = useState("");
  const [courseId, setCourseId] = useState<string | null>(null);
  const [courseTitle, setCourseTitle] = useState<string | null>(null);
  const [topics, setTopics] = useState<string[]>([]);
  const [apiFocusTopic, setApiFocusTopic] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      setLoading(true);
      const params = new URLSearchParams();
      if (queryCourseId) params.set("courseId", queryCourseId);
      if (urlTopic) params.set("topic", urlTopic);
      const query = params.toString();
      const response = await fetch(
        `/api/study/mixed-review${query ? `?${query}` : ""}`,
      );
      const data = await response.json();
      if (data.success) {
        setSteps(data.data.steps);
        setSummary(data.data.summary);
        setCourseId(data.data.courseId ?? null);
        setCourseTitle(data.data.courseTitle ?? null);
        setTopics(Array.isArray(data.data.topics) ? data.data.topics : []);
        setApiFocusTopic(
          typeof data.data.focusTopic === "string" ? data.data.focusTopic : null,
        );
      }
      setLoading(false);
    }
    void load();
  }, [queryCourseId, urlTopic]);

  function startAsSession() {
    const focusTopic = resolveLoopFocusTopic(urlTopic, topics) || apiFocusTopic;
    saveStudySession({
      summary,
      totalMinutes: 30,
      activityType: "NOTES_REVIEW",
      courseId,
      courseTitle,
      coldStartTopic: focusTopic,
      blocks: steps.map((step) => ({
        id: step.id,
        minutes: step.minutes,
        label: step.label,
        activity: step.activity,
        href: step.href,
        topicName: focusTopic ?? undefined,
      })),
    });
    const params = new URLSearchParams({ minutes: "30" });
    if (courseId) params.set("courseId", courseId);
    window.location.href = `/study/session?${params.toString()}`;
  }

  if (loading) {
    return (
      <div className="flex min-h-[40vh] items-center justify-center">
        <Loader2 className="h-6 w-6 animate-spin text-violet-600" />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-2xl space-y-8 px-4 py-8">
      <div>
        <p className="text-xs font-bold uppercase tracking-[0.2em] text-violet-600">
          Lucky · Mixed Review
        </p>
        <h1 className="mt-1 text-3xl font-black text-stone-900">Your personalized review</h1>
        <p className="mt-2 text-stone-600">{summary}</p>
      </div>

      {courseId && courseTitle ? (
        <StudyLoopStrip
          courseId={courseId}
          courseTitle={courseTitle}
          topics={topics}
          focusTopic={resolveLoopFocusTopic(urlTopic, topics) || apiFocusTopic}
        />
      ) : null}

      <ul className="space-y-3">
        {steps.map((step, index) => (
          <li
            key={step.id}
            className="flex items-center justify-between gap-4 rounded-2xl border border-violet-100 bg-violet-50/40 px-4 py-4"
          >
            <div>
              <p className="text-xs font-bold text-violet-600">Step {index + 1}</p>
              <p className="font-semibold text-stone-900">{step.label}</p>
              <p className="text-sm text-stone-600">{step.reason}</p>
            </div>
            <div className="text-right">
              <p className="text-xs text-stone-500">{step.minutes} min</p>
              <Link
                href={step.href}
                data-hub-chrome
                className="inline-flex min-h-11 items-center text-sm font-semibold text-violet-600 hover:underline touch-manipulation"
              >
                Open →
              </Link>
            </div>
          </li>
        ))}
      </ul>

      <button
        type="button"
        onClick={startAsSession}
        className="inline-flex min-h-11 w-full items-center justify-center gap-2 rounded-xl bg-violet-600 px-5 py-3 text-sm font-semibold text-white hover:bg-violet-500 touch-manipulation"
      >
        <Play className="h-4 w-4" /> Run as guided session
      </button>
    </div>
  );
}

#!/usr/bin/env node
/**
 * Read-only diagnostic for Course Info planning.
 * Outputs sanitized response shapes — no secrets in output.
 */
import { readFileSync } from "fs";
import { resolve } from "path";

function loadEnv() {
  try {
    const envPath = resolve(process.cwd(), ".env");
    const text = readFileSync(envPath, "utf8");
    for (const line of text.split("\n")) {
      const m = line.match(/^([A-Z_]+)=(.*)$/);
      if (!m) continue;
      const key = m[1];
      let val = m[2].trim();
      if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
        val = val.slice(1, -1);
      }
      if (!process.env[key]) process.env[key] = val;
    }
  } catch {
    // ignore
  }
}

loadEnv();

const BASE_URL = (process.env.MOODLE_URL ?? "").replace(/\?.*$/, "").replace(/\/$/, "");
const TOKEN = (process.env.MOODLE_TOKEN ?? "").trim();

function sanitize(value, depth = 0) {
  if (value === null || value === undefined) return value;
  if (depth > 6) return "[nested]";
  if (typeof value === "string") {
    if (value.length > 200 && (value.startsWith("data:") || value.includes("base64"))) {
      return `[string ${value.length} chars, truncated]`;
    }
    if (value.includes("@") && value.includes(".")) return "[email redacted]";
    if (value.length > 300) return `${value.slice(0, 300)}… [${value.length} chars]`;
    return value;
  }
  if (Array.isArray(value)) {
    if (value.length === 0) return [];
    const sample = sanitize(value[0], depth + 1);
    return { _arrayLength: value.length, _sampleItem: sample };
  }
  if (typeof value === "object") {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = sanitize(v, depth + 1);
    }
    return out;
  }
  return value;
}

async function callMoodle(wsfunction, extraParams = {}) {
  const params = new URLSearchParams({
    wstoken: TOKEN,
    wsfunction,
    moodlewsrestformat: "json",
    ...extraParams,
  });
  const url = `${BASE_URL}/webservice/rest/server.php?${params.toString()}`;

  const result = {
    wsfunction,
    httpStatus: null,
    ok: false,
    errorcode: null,
    message: null,
    exception: null,
    shape: null,
  };

  try {
    const response = await fetch(url, { cache: "no-store", signal: AbortSignal.timeout(30_000) });
    result.httpStatus = response.status;
    const text = await response.text();
    let data;
    try {
      data = JSON.parse(text);
    } catch {
      result.message = "invalid JSON";
      return result;
    }
    if (data?.exception) {
      result.errorcode = data.errorcode ?? null;
      result.message = data.message ?? data.exception;
      result.exception = data.exception;
      return result;
    }
    result.ok = true;
    result.shape = sanitize(data);
    return result;
  } catch (error) {
    result.message = error instanceof Error ? error.message : String(error);
    return result;
  }
}

async function main() {
  if (!BASE_URL || !TOKEN) {
    console.error("MOODLE_URL and MOODLE_TOKEN required in .env");
    process.exit(1);
  }

  const report = { site: BASE_URL, tests: [] };

  const siteInfo = await callMoodle("core_webservice_get_site_info");
  report.tests.push(siteInfo);
  const functionNames = siteInfo.ok
    ? (siteInfo.shape?.functions?._sampleItem
        ? "see full count below"
        : null)
    : null;

  const enrolled = await callMoodle(
    "core_course_get_enrolled_courses_by_timeline_classification",
    { classification: "all", limit: "50", offset: "0" },
  );
  report.tests.push(enrolled);

  let courseId = null;
  if (enrolled.ok && enrolled.shape?.courses?._sampleItem?.id) {
    courseId = enrolled.shape.courses._sampleItem.id;
  } else if (enrolled.ok && enrolled.shape?.courses?._arrayLength) {
    // need raw id - re-fetch one course id only
    const raw = await fetch(
      `${BASE_URL}/webservice/rest/server.php?` +
        new URLSearchParams({
          wstoken: TOKEN,
          wsfunction: "core_course_get_enrolled_courses_by_timeline_classification",
          moodlewsrestformat: "json",
          classification: "all",
          limit: "5",
          offset: "0",
        }),
    );
    const rawData = await raw.json();
    courseId = rawData?.courses?.find((c) => c.id > 1)?.id ?? rawData?.courses?.[0]?.id;
  }

  report.primaryCourseId = courseId;

  if (courseId) {
    report.tests.push(
      await callMoodle("core_course_get_contents", { courseid: String(courseId) }),
    );
    report.tests.push(
      await callMoodle("mod_assign_get_assignments", { "courseids[0]": String(courseId) }),
    );
    const now = Math.floor(Date.now() / 1000);
    const later = now + 120 * 24 * 3600;
    report.tests.push(
      await callMoodle("core_calendar_get_calendar_events", {
        "events[courseids][0]": String(courseId),
        "options[userevents]": "0",
        "options[siteevents]": "0",
        "options[timestart]": String(now),
        "options[timeend]": String(later),
      }),
    );
    // Extra: instructor-related mobile WS
    for (const [fn, extraParams] of [
      ["mod_book_get_books_by_courses", { "courseids[0]": String(courseId) }],
      ["mod_page_get_pages_by_courses", { "courseids[0]": String(courseId) }],
      ["core_enrol_get_enrolled_users", { courseid: String(courseId) }],
    ]) {
      const extra = await callMoodle(fn, extraParams);
      report.tests.push(extra);
    }
  }

  // Function list count from raw site_info
  if (siteInfo.ok) {
    const raw = await fetch(
      `${BASE_URL}/webservice/rest/server.php?` +
        new URLSearchParams({
          wstoken: TOKEN,
          wsfunction: "core_webservice_get_site_info",
          moodlewsrestformat: "json",
        }),
    );
    const rawSite = await raw.json();
    report.tokenFunctionCount = rawSite.functions?.length ?? 0;
    report.studyHaulFunctions = [
      "core_webservice_get_site_info",
      "core_course_get_enrolled_courses_by_timeline_classification",
      "core_course_get_contents",
      "mod_assign_get_assignments",
      "mod_assign_get_grades",
      "core_calendar_get_calendar_events",
      "mod_book_get_books_by_courses",
      "mod_page_get_pages_by_courses",
      "core_enrol_get_enrolled_users",
    ].map((name) => ({
      name,
      onToken: Boolean(rawSite.functions?.some((f) => f.name === name)),
    }));
  }

  console.log(JSON.stringify(report, null, 2));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * One-off Moodle Mobile Web Service audit.
 * Usage: MOODLE_URL=... MOODLE_TOKEN=... node scripts/moodle-ws-audit.mjs
 * Does NOT modify application code.
 */

const BASE_URL = (process.env.MOODLE_URL ?? "https://moodle.lsua.edu").replace(/\?.*$/, "").replace(/\/$/, "");
const TOKEN = (process.env.MOODLE_TOKEN ?? "").trim();

function maskToken(url) {
  return url.replace(/wstoken=[^&]+/, "wstoken=***REDACTED***");
}

function summarize(value, maxLen = 2000) {
  const json = JSON.stringify(value, null, 2);
  if (json.length <= maxLen) return json;
  return `${json.slice(0, maxLen)}\n... [truncated, ${json.length} chars total]`;
}

async function callMoodle(wsfunction, extraParams = {}) {
  const params = new URLSearchParams({
    wstoken: TOKEN,
    wsfunction,
    moodlewsrestformat: "json",
    ...extraParams,
  });
  const url = `${BASE_URL}/webservice/rest/server.php?${params.toString()}`;
  const requestLog = maskToken(url);

  const result = {
    wsfunction,
    request: requestLog,
    httpStatus: null,
    moodleError: null,
    parsed: null,
    ok: false,
  };

  let response;
  try {
    response = await fetch(url, { cache: "no-store", signal: AbortSignal.timeout(30_000) });
  } catch (error) {
    result.moodleError = {
      type: "network",
      message: error instanceof Error ? error.message : String(error),
      cause: error instanceof Error && error.cause ? String(error.cause) : undefined,
    };
    return result;
  }

  result.httpStatus = response.status;
  const contentType = response.headers.get("content-type") ?? "";
  const text = await response.text();

  if (text.trimStart().startsWith("<!") || text.includes("<!DOCTYPE")) {
    result.moodleError = {
      type: "html_response",
      message: "Moodle returned HTML instead of JSON",
      preview: text.slice(0, 300),
    };
    return result;
  }

  let data;
  try {
    data = JSON.parse(text);
  } catch {
    result.moodleError = {
      type: "invalid_json",
      message: "Response is not valid JSON",
      preview: text.slice(0, 300),
    };
    return result;
  }

  result.parsed = data;

  if (data && typeof data === "object" && data.exception) {
    result.moodleError = {
      type: "moodle_exception",
      exception: data.exception,
      errorcode: data.errorcode ?? null,
      message: data.message ?? data.exception,
    };
    return result;
  }

  if (!response.ok) {
    result.moodleError = {
      type: "http_error",
      message: `HTTP ${response.status}`,
    };
    return result;
  }

  result.ok = true;
  return result;
}

function logResult(label, result) {
  console.log("\n" + "=".repeat(72));
  console.log(`TEST: ${label}`);
  console.log("=".repeat(72));
  console.log("Moodle function:", result.wsfunction);
  console.log("HTTP request:", result.request);
  console.log("HTTP status:", result.httpStatus ?? "N/A (network failure)");
  if (result.moodleError) {
    console.log("Moodle error:", JSON.stringify(result.moodleError, null, 2));
  } else {
    console.log("Moodle error: none");
  }
  console.log("Parsed response:", summarize(result.parsed));
  console.log("Result:", result.ok ? "SUCCESS" : "FAIL");
}

function findSyllabusCandidates(contents) {
  const candidates = [];
  if (!Array.isArray(contents)) return candidates;

  for (const section of contents) {
    const sectionName = section.name ?? `Section ${section.section ?? "?"}`;
    for (const mod of section.modules ?? []) {
      const name = (mod.name ?? "").toLowerCase();
      const modtype = mod.modname ?? mod.modtype ?? "unknown";
      const looksLikeSyllabus =
        /syllabus|course outline|course information|course info/i.test(mod.name ?? "") ||
        (modtype === "resource" && /syllabus|outline/i.test(name)) ||
        (modtype === "folder" && /syllabus|outline/i.test(name)) ||
        (modtype === "page" && /syllabus|outline|welcome|information/i.test(name));

      if (looksLikeSyllabus || modtype === "resource" || modtype === "folder") {
        candidates.push({
          section: sectionName,
          moduleId: mod.id,
          instanceId: mod.instance,
          modtype,
          name: mod.name,
          url: mod.url ?? null,
          contents: mod.contents ?? null,
          description: mod.description ? String(mod.description).slice(0, 200) : null,
          flaggedAsSyllabus: looksLikeSyllabus,
        });
      }
    }
  }
  return candidates;
}

async function main() {
  if (!TOKEN) {
    console.error("Set MOODLE_TOKEN environment variable.");
    process.exit(1);
  }

  console.log("Moodle Web Service Audit");
  console.log("Site:", BASE_URL);
  console.log("Token length:", TOKEN.length, "chars");
  console.log("Scope: Moodle Mobile Web Service functions only");

  const results = [];

  // 1. Auth / current user
  const siteInfo = await callMoodle("core_webservice_get_site_info");
  logResult("Authentication & current user (core_webservice_get_site_info)", siteInfo);
  results.push({ label: "core_webservice_get_site_info", ...siteInfo });

  let userId = null;
  if (siteInfo.ok && siteInfo.parsed?.userid) {
    userId = siteInfo.parsed.userid;
  }

  // Alternative user info if site_info works
  if (userId) {
    const userInfo = await callMoodle("core_user_get_users_by_field", {
      field: "id",
      "values[0]": String(userId),
    });
    logResult("Current user details (core_user_get_users_by_field)", userInfo);
    results.push({ label: "core_user_get_users_by_field", ...userInfo });
  }

  // 2. Enrolled courses
  const enrolledTimeline = await callMoodle(
    "core_course_get_enrolled_courses_by_timeline_classification",
    { classification: "all", limit: "50", offset: "0" },
  );
  logResult(
    "Enrolled courses (core_course_get_enrolled_courses_by_timeline_classification)",
    enrolledTimeline,
  );
  results.push({
    label: "core_course_get_enrolled_courses_by_timeline_classification",
    ...enrolledTimeline,
  });

  const enrolledLegacy = await callMoodle("core_enrol_get_users_courses", {
    userid: String(userId ?? "0"),
  });
  logResult("Enrolled courses legacy (core_enrol_get_users_courses)", enrolledLegacy);
  results.push({ label: "core_enrol_get_users_courses", ...enrolledLegacy });

  // Pick first real course id
  let courseId = null;
  let courseName = null;
  const courseListRaw =
    enrolledTimeline.parsed?.courses ??
    (Array.isArray(enrolledTimeline.parsed) ? enrolledTimeline.parsed : null) ??
    enrolledLegacy.parsed ??
    [];
  const courseList = Array.isArray(courseListRaw) ? courseListRaw : [];

  for (const c of courseList) {
    if (c.id && c.id > 1) {
      courseId = c.id;
      courseName = c.fullname ?? c.shortname ?? String(c.id);
      break;
    }
  }

  console.log(`\n--- Selected course for deep tests: ${courseId} ${courseName ?? "(none)"} ---`);

  if (!courseId) {
    console.log("No enrolled course found; skipping course-scoped tests.");
  } else {
    // 3. Course contents / modules (syllabus discovery)
    const contents = await callMoodle("core_course_get_contents", {
      courseid: String(courseId),
    });
    logResult(`Course contents (core_course_get_contents) courseId=${courseId}`, contents);
    results.push({ label: "core_course_get_contents", ...contents });

    if (contents.ok) {
      const syllabusCandidates = findSyllabusCandidates(contents.parsed);
      console.log("\n--- Syllabus / resource module scan ---");
      console.log(
        summarize(
          {
            courseId,
            courseName,
            totalSections: Array.isArray(contents.parsed) ? contents.parsed.length : 0,
            syllabusCandidates,
            allModuleTypes: [
              ...new Set(
                (contents.parsed ?? []).flatMap((s) =>
                  (s.modules ?? []).map((m) => m.modname ?? m.modtype),
                ),
              ),
            ],
          },
          4000,
        ),
      );
    }

    // 4. Assignments
    const assignments = await callMoodle("mod_assign_get_assignments", {
      "courseids[0]": String(courseId),
    });
    logResult(`Assignments (mod_assign_get_assignments) courseId=${courseId}`, assignments);
    results.push({ label: "mod_assign_get_assignments", ...assignments });

    let assignmentId = null;
    const assignCourse = assignments.parsed?.courses?.find((c) => c.id === courseId);
    if (assignCourse?.assignments?.length) {
      assignmentId = assignCourse.assignments[0].id;
    }

    if (assignmentId) {
      const grades = await callMoodle("mod_assign_get_grades", {
        "assignmentids[0]": String(assignmentId),
      });
      logResult(`Assignment grades (mod_assign_get_grades) assignmentId=${assignmentId}`, grades);
      results.push({ label: "mod_assign_get_grades", ...grades });
    } else {
      console.log("\nNo assignments in first course; skipping mod_assign_get_grades.");
    }

    // 5. Calendar events
    const now = Math.floor(Date.now() / 1000);
    const later = now + 120 * 24 * 60 * 60;
    const calendar = await callMoodle("core_calendar_get_calendar_events", {
      "events[courseids][0]": String(courseId),
      "options[userevents]": "0",
      "options[siteevents]": "0",
      "options[timestart]": String(now),
      "options[timeend]": String(later),
    });
    logResult(`Calendar events (core_calendar_get_calendar_events) courseId=${courseId}`, calendar);
    results.push({ label: "core_calendar_get_calendar_events", ...calendar });
  }

  // Summary
  console.log("\n" + "#".repeat(72));
  console.log("SUMMARY");
  console.log("#".repeat(72));
  for (const r of results) {
    const err =
      r.moodleError?.errorcode ??
      r.moodleError?.message ??
      r.moodleError?.type ??
      "none";
    console.log(
      `${r.ok ? "OK " : "FAIL"} | ${r.label} | HTTP ${r.httpStatus ?? "—"} | ${err}`,
    );
  }
}

main().catch((error) => {
  console.error("Audit crashed:", error);
  process.exit(1);
});

