"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { BookOpen, Plus } from "lucide-react";

import { BulkSelectionBar } from "@/components/ui/BulkSelectionBar";
import { SelectCheckbox } from "@/components/ui/SelectCheckbox";
import { PAGE_TEMPLATES, resolveNotebookCoverStyle } from "@/lib/core/page-templates";
import type { NoteDocument } from "@/lib/core/note-types";
import { confirmDeleteMany } from "@/lib/confirm-delete";
import { useSelectableIds } from "@/lib/selection/use-selectable-ids";

export interface ShelfNote {
  id: string;
  title: string | null;
  method: string;
  updatedAt: string;
  contentJson: string | null;
  course?: { id: string; title: string; color: string | null } | null;
}

function parseNotebook(contentJson: string | null) {
  if (!contentJson) return {} as NonNullable<NoteDocument["notebook"]>;
  try {
    const doc = JSON.parse(contentJson) as NoteDocument;
    return doc.notebook ?? {};
  } catch {
    return {};
  }
}

/**
 * Shelf UI — open uses native GET forms so iPad Safari always navigates.
 * Delete uses the shared select-all / select-one / bulk-delete pattern.
 */
export function NotebookShelfView({ initialNotes }: { initialNotes: ShelfNote[] }) {
  const router = useRouter();
  const [notes, setNotes] = useState(initialNotes);
  const ids = useMemo(() => notes.map((n) => n.id), [notes]);
  const selection = useSelectableIds(ids);
  const [bulkDeleting, setBulkDeleting] = useState(false);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- sync UI state to props or external subscription
    setNotes(initialNotes);
  }, [initialNotes]);

  useEffect(() => {
    selection.pruneTo(ids);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ids.join("|")]);

  async function deleteSelected() {
    const selected = selection.selectedIds;
    if (selected.length === 0) return;
    if (
      !confirmDeleteMany(selected.length, {
        noun: "notebook",
        detail: "covers, pages, and writing in these notebooks will be removed",
      })
    ) {
      return;
    }
    setBulkDeleting(true);
    try {
      const response = await fetch("/api/notes", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ids: selected }),
      });
      const data = (await response.json()) as { success?: boolean; error?: string };
      if (!response.ok || !data.success) {
        throw new Error(data.error ?? "Could not delete notebooks.");
      }
      setNotes((prev) => prev.filter((n) => !selected.includes(n.id)));
      selection.clear();
      router.refresh();
    } catch (error) {
      window.alert(error instanceof Error ? error.message : "Could not delete notebooks.");
    } finally {
      setBulkDeleting(false);
    }
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-8">
      <div className="mb-6 flex flex-wrap items-center gap-2">
        <a
          href="/core"
          className="inline-flex min-h-11 items-center rounded-xl border border-brand bg-brand-soft px-4 py-2.5 text-sm font-semibold text-stone-800 touch-manipulation"
          style={{ WebkitTapHighlightColor: "transparent" }}
        >
          ← Back to notebook
        </a>
      </div>

      <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-xs font-bold uppercase tracking-wider text-teal-600">Core</p>
          <h1 className="text-3xl font-bold text-stone-900">Notebook shelf</h1>
          <p className="mt-1 text-sm text-stone-600">
            Covers and paper you picked — open any notebook and keep writing.
          </p>
        </div>
        <a
          href="/core/go/new"
          className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-stone-900 px-4 py-2.5 text-sm font-semibold text-white touch-manipulation"
          style={{ WebkitTapHighlightColor: "transparent" }}
        >
          <Plus className="h-4 w-4" />
          New notebook
        </a>
      </div>

      {notes.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-orange-200 bg-white px-6 py-16 text-center">
          <BookOpen className="mx-auto h-10 w-10 text-orange-300" />
          <p className="mt-3 font-semibold text-stone-800">No notebooks yet</p>
          <p className="mt-1 text-sm text-stone-500">
            Create one with a cover + paper template from Core, or{" "}
            <a href="/courses" className="font-semibold text-teal-700 hover:underline">
              upload a syllabus
            </a>{" "}
            for a cold-start study pack.
          </p>
          <a
            href="/core"
            className="mt-4 inline-flex min-h-11 items-center text-sm font-semibold text-teal-600 touch-manipulation"
          >
            Go to Core Notes →
          </a>
        </div>
      ) : (
        <div className="space-y-4">
          <BulkSelectionBar
            totalCount={notes.length}
            selectedCount={selection.selectedCount}
            allSelected={selection.allSelected}
            someSelected={selection.someSelected}
            onToggleAll={selection.toggleAll}
            onClear={selection.clear}
            onDeleteSelected={() => void deleteSelected()}
            deleting={bulkDeleting}
            noun="notebook"
          />
          <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
            {notes.map((note) => {
              const notebook = parseNotebook(note.contentJson);
              const cover = resolveNotebookCoverStyle(notebook);
              const paperLabel =
                PAGE_TEMPLATES.find((t) => t.id === notebook.pageTemplateId)?.label ?? "Paper";
              const title = note.title?.trim() || "Untitled";
              const selected = selection.isSelected(note.id);
              return (
                <div
                  key={note.id}
                  className={`relative ${
                    selected ? "ring-2 ring-[var(--sh-primary,#ea580c)] ring-offset-2 rounded-2xl" : ""
                  }`}
                  data-shelf-note-id={note.id}
                >
                  <div className="absolute left-1 top-1 z-10">
                    <SelectCheckbox
                      checked={selected}
                      onChange={() => selection.toggle(note.id)}
                      label={`Select ${title}`}
                      className="rounded-lg bg-white/90 shadow-sm"
                    />
                  </div>
                  <form action="/core" method="get" className="m-0">
                    <input type="hidden" name="noteId" value={note.id} />
                    <button
                      type="submit"
                      className="group w-full rounded-2xl border border-orange-100 bg-white p-2 text-left shadow-sm transition hover:-translate-y-1 hover:shadow-lg touch-manipulation"
                      style={{
                        WebkitTapHighlightColor: "transparent",
                        touchAction: "manipulation",
                      }}
                    >
                      <div
                        className={`pointer-events-none relative aspect-[3/4] overflow-hidden rounded-xl ${cover.className ?? ""}`}
                        style={cover.style}
                      >
                        <div className="absolute inset-y-0 left-0 w-2 bg-black/15" />
                        <div
                          data-notebook-binding
                          className="absolute inset-y-3 left-1 w-3 opacity-80"
                          aria-hidden
                        />
                        <div className="absolute inset-0 flex flex-col justify-end p-3">
                          <p
                            className={`line-clamp-3 text-sm font-black leading-snug ${cover.titleClassName}`}
                          >
                            {title}
                          </p>
                          <p
                            className={`mt-1 text-[10px] font-semibold ${cover.titleClassName} opacity-75`}
                          >
                            {paperLabel}
                          </p>
                        </div>
                        <div className="absolute inset-x-0 bottom-0 h-3 bg-white/90 shadow-inner" />
                      </div>
                      <p className="pointer-events-none mt-2 truncate text-sm font-semibold text-stone-900 group-hover:text-teal-700">
                        {title}
                      </p>
                      <p className="pointer-events-none truncate text-[10px] text-stone-400">
                        {note.course?.title ?? "No course"} ·{" "}
                        {new Date(note.updatedAt).toLocaleDateString()}
                      </p>
                    </button>
                  </form>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

import { TransformableElement } from "@/components/core/canvas/TransformableElement";
import { CANVAS_ELEMENT_BASE_Z, nextCanvasElementZIndex } from "@/lib/core/canvas-layer";
import { getFormatDefinition } from "@/lib/core/format-catalog";
import {
  ensureBlockPositions,
  rectsOverlap,
} from "@/lib/core/block-layout";
import { reflowSectionsToRegions } from "@/lib/core/study-page-plan";
import { hasLockedStudyTemplateLayout } from "@/lib/core/study-templates";
import type { CompositeSection, NoteDocument } from "@/lib/core/note-types";
import { removeCompositeSection } from "@/lib/core/section-format-data";
import { FormatBlockEditor } from "@/components/core/CompositeFormatSections";

function sectionRect(section: CompositeSection) {
  return {
    x: section.x ?? 0,
    y: section.y ?? 0,
    width: section.width ?? 0,
    height: section.height ?? 0,
  };
}

function sectionsOverlap(sections: CompositeSection[]): boolean {
  for (let i = 0; i < sections.length; i++) {
    for (let j = i + 1; j < sections.length; j++) {
      if (rectsOverlap(sectionRect(sections[i]!), sectionRect(sections[j]!), 4)) {
        return true;
      }
    }
  }
  return false;
}

export function PageFormatBlocksLayer({
  sections,
  doc,
  setDoc,
  selectedIds,
  onSelect,
  editable = true,
}: {
  sections: CompositeSection[];
  doc: NoteDocument;
  setDoc: (updater: (current: NoteDocument) => NoteDocument) => void;
  selectedIds: string[];
  onSelect: (ids: string[]) => void;
  editable?: boolean;
}) {
  const positioned = ensureBlockPositions(sections);
  const selectedSet = new Set(selectedIds);
  const repairKey = positioned
    .map((section) => `${section.id}:${section.x}:${section.y}:${section.width}:${section.height}`)
    .join("|");
  const lastRepairKey = useRef("");

  function bringToFront(id: string) {
    const next = nextCanvasElementZIndex(doc);
    patchSections(
      positioned.map((section) =>
        section.id === id ? { ...section, zIndex: next } : section,
      ),
    );
  }

  function handleSelect(id: string, options?: { shiftKey?: boolean }) {
    if (options?.shiftKey) {
      if (selectedSet.has(id)) {
        onSelect(selectedIds.filter((entry) => entry !== id));
      } else {
        onSelect([...selectedIds, id]);
        bringToFront(id);
      }
      return;
    }
    onSelect([id]);
    bringToFront(id);
  }

  function patchSections(next: CompositeSection[]) {
    setDoc((current) => ({
      ...current,
      metadata: {
        ...current.metadata,
        compositeSections: next,
        activeFormat: "BLANK",
      },
    }));
  }

  function patchSection(id: string, patch: Partial<CompositeSection>) {
    patchSections(
      positioned.map((section) => (section.id === id ? { ...section, ...patch } : section)),
    );
  }

  useEffect(() => {
    if (lastRepairKey.current === repairKey) return;
    if (hasLockedStudyTemplateLayout(doc) || positioned.length < 2 || !sectionsOverlap(positioned)) {
      lastRepairKey.current = repairKey;
      return;
    }
    lastRepairKey.current = repairKey;
    patchSections(reflowSectionsToRegions(positioned, positioned[0]?.y ?? 48));
  }, [repairKey, doc.metadata?.studyTemplateId]);

  return (
    <>
      {positioned.map((section) => {
        const def = getFormatDefinition(section.formatId);
        const blockX = section.x ?? 32;
        const blockY = section.y ?? 32;
        const blockW = section.width ?? 300;
        const blockH = section.height ?? 140;
        const isActive = selectedSet.has(section.id);

        return (
          <TransformableElement
            key={section.id}
            elementId={section.id}
            dragFromHandleOnly
            quietChrome
            rect={{
              x: blockX,
              y: blockY,
              width: blockW,
              height: blockH,
            }}
            selected={isActive}
            editable={editable}
            zIndex={section.zIndex ?? CANVAS_ELEMENT_BASE_Z}
            onSelect={(options) => handleSelect(section.id, options)}
            onChange={(patch) => {
              patchSection(section.id, {
                x: patch.x ?? blockX,
                y: patch.y ?? blockY,
                width: patch.width ?? blockW,
                height: patch.height ?? blockH,
              });
            }}
            onDelete={() => {
              setDoc((current) => removeCompositeSection(current, section.id));
              if (selectedSet.has(section.id)) {
                onSelect(selectedIds.filter((entry) => entry !== section.id));
              }
            }}
            onLayerForward={() =>
              patchSection(section.id, {
                zIndex: (section.zIndex ?? CANVAS_ELEMENT_BASE_Z) + 1,
              })
            }
            onLayerBackward={() =>
              patchSection(section.id, {
                zIndex: Math.max(
                  CANVAS_ELEMENT_BASE_Z,
                  (section.zIndex ?? CANVAS_ELEMENT_BASE_Z) - 1,
                ),
              })
            }
          >
            <div
              className={`flex h-full min-h-0 min-w-0 flex-col overflow-hidden rounded-sm ${
                isActive
                  ? ""
                  : "outline outline-1 outline-dashed outline-transparent hover:outline-stone-300/80"
              }`}
              data-format-block={section.id}
              onPointerDown={(event) => {
                if (!editable) return;
                if (!isActive) {
                  event.stopPropagation();
                  handleSelect(section.id, { shiftKey: event.shiftKey });
                }
              }}
            >
              <p
                className={`shrink-0 truncate px-0.5 text-[10px] font-semibold uppercase tracking-wider ${
                  isActive ? "mb-1 text-stone-500" : "mb-0.5 text-stone-400/80"
                }`}
              >
                {section.title || def.label}
              </p>
              <div className="min-h-0 min-w-0 flex-1 overflow-auto break-words [overflow-wrap:anywhere]">
                <FormatBlockEditor
                  section={section}
                  doc={doc}
                  setDoc={setDoc}
                  bare
                  selected={isActive}
                />
              </div>
            </div>
          </TransformableElement>
        );
      })}
    </>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import type { SketchStroke } from "@/lib/core/note-types";
import type { InkTool } from "@/lib/core/ink-engine";
import { SketchLayer } from "@/components/core/SketchLayer";
import { PdfPageCanvas } from "@/components/core/PdfPageCanvas";

/**
 * One PDF page bitmap + page-keyed ink (used in continuous scroll).
 */
export function PdfAnnotatedPage({
  materialId,
  doc,
  docVersion,
  pageNumber,
  zoom,
  active,
  inkTool,
  color,
  lineWidth,
  pencilOnly,
  onPencilOnlyChange,
  pressureSensitivity,
  tipFlatness,
  tipSharpness,
  strokeType,
  reduceLatency,
  inkMedium,
  onError,
}: {
  materialId: string;
  doc: import("@/lib/core/pdfjs-client").PdfDoc | null;
  docVersion: number;
  pageNumber: number;
  zoom: number;
  active: boolean;
  inkTool: InkTool;
  color: string;
  lineWidth: number;
  pencilOnly: boolean;
  onPencilOnlyChange: (value: boolean) => void;
  pressureSensitivity: number;
  tipFlatness: number;
  tipSharpness: number;
  strokeType: "solid" | "dashed" | "dotted";
  reduceLatency: boolean;
  inkMedium: "ink" | "chalk" | "crayon" | "colorPencil" | "marker";
  onError?: (message: string | null) => void;
}) {
  const [strokes, setStrokes] = useState<SketchStroke[]>([]);
  const [ready, setReady] = useState(false);
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let cancelled = false;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- sync UI state to props or external subscription
    setReady(false);
    void fetch(`/api/materials/${materialId}/annotations?page=${pageNumber}`)
      .then((response) => response.json())
      .then((data) => {
        if (cancelled) return;
        if (data.success) {
          setStrokes((data.data.strokes ?? []) as SketchStroke[]);
        } else {
          setStrokes([]);
        }
      })
      .catch(() => {
        if (!cancelled) setStrokes([]);
      })
      .finally(() => {
        if (!cancelled) setReady(true);
      });
    return () => {
      cancelled = true;
      if (saveTimer.current) clearTimeout(saveTimer.current);
    };
  }, [materialId, pageNumber]);

  const persistStrokes = useCallback(
    (nextStrokes: SketchStroke[]) => {
      setStrokes(nextStrokes);
      if (saveTimer.current) clearTimeout(saveTimer.current);
      saveTimer.current = setTimeout(() => {
        const rect = wrapRef.current?.querySelector("canvas")?.getBoundingClientRect();
        const viewport =
          rect && rect.width > 0 && rect.height > 0
            ? { width: rect.width, height: rect.height }
            : undefined;
        void fetch(`/api/materials/${materialId}/annotations`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ pageNumber, strokes: nextStrokes, viewport }),
        }).catch(() => onError?.("Failed to save ink on this page."));
      }, 600);
    },
    [materialId, pageNumber, onError],
  );

  return (
    <div
      ref={wrapRef}
      data-pdf-page={pageNumber}
      className="relative mx-auto mb-4 w-full max-w-4xl scroll-mt-4"
    >
      <div className="mb-1 text-[10px] font-semibold uppercase tracking-wider text-stone-500">
        Page {pageNumber}
      </div>
      <div
        data-notebook-paper="true"
        data-page-active={active ? "true" : undefined}
        className="overflow-hidden rounded-sm shadow-[0_10px_36px_rgba(28,25,23,0.16),0_2px_6px_rgba(28,25,23,0.08)] ring-1 ring-stone-900/10"
      >
        <PdfPageCanvas
          doc={doc}
          docVersion={docVersion}
          pageNumber={pageNumber}
          zoom={zoom}
          onError={onError}
        >
          <SketchLayer
            strokes={strokes}
            onChange={persistStrokes}
            active={active && ready}
            color={color}
            lineWidth={lineWidth}
            inkTool={inkTool}
            pencilOnly={pencilOnly}
            pressureSensitivity={pressureSensitivity}
            tipFlatness={tipFlatness}
            tipSharpness={tipSharpness}
            strokeType={strokeType}
            reduceLatency={reduceLatency}
            inkMedium={inkMedium}
            onPenDetected={() => {
              // Keep finger writing available — never auto Pencil-only on PDF.
            }}
            className="absolute inset-0 h-full w-full"
          />
        </PdfPageCanvas>
      </div>
    </div>
  );
}

