"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { Loader2, Play, Sparkles } from "lucide-react";

import { StudyLoopStrip } from "@/components/study/StudyLoopStrip";
import { luckyQuizHref, sixChunkingHref } from "@/lib/study/loop-hrefs";
import { resolveLoopFocusTopic } from "@/lib/study/resolve-loop-focus-topic";
import { resolveUrlCourseId } from "@/lib/study/resolve-url-course-id";

interface CourseOption {
  id: string;
  title: string;
  topics?: string[];
}

interface Problem {
  language: string;
  title: string;
  prompt: string;
  starter: string;
}

interface CodeEvaluation {
  score: number;
  summary: string;
  correctness: string;
  edgeCases: string[];
  improvements: string[];
  complexity: string;
}

export function CodePracticeWorkspace({
  initialCourses,
}: {
  initialCourses: CourseOption[];
}) {
  const searchParams = useSearchParams();
  const urlTopic = searchParams.get("topic")?.trim() || null;
  const [courses] = useState(initialCourses);
  const courseIds = useMemo(() => courses.map((course) => course.id), [courses]);
  const [problems, setProblems] = useState<Problem[]>([]);
  const [language, setLanguage] = useState("javascript");
  const [courseId, setCourseId] = useState(() =>
    resolveUrlCourseId(searchParams.get("courseId"), courseIds),
  );
  const [code, setCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<CodeEvaluation | null>(null);
  const [error, setError] = useState<string | null>(null);
  const sessionStart = useRef(Date.now());

  const activeProblem =
    problems.find((problem) => problem.language === language) ?? problems[0];

  const selectedCourse = useMemo(
    () => courses.find((course) => course.id === courseId),
    [courses, courseId],
  );
  const focusTopic = resolveLoopFocusTopic(urlTopic, selectedCourse?.topics ?? []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- sync UI state to props or external subscription
    setCourseId(resolveUrlCourseId(searchParams.get("courseId"), courseIds));
  }, [searchParams, courseIds]);

  useEffect(() => {
    void fetch("/api/study/code-evaluate")
      .then((response) => response.json())
      .then((data) => {
        if (data.success) {
          setProblems(data.data);
          setCode(data.data[0]?.starter ?? "");
        }
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- sync UI state to props or external subscription
    if (activeProblem) setCode(activeProblem.starter);
    setResult(null);
  }, [language, activeProblem?.language]);

  async function evaluate() {
    if (!code.trim()) {
      setError("Write some code first.");
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const response = await fetch("/api/study/code-evaluate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          courseId: courseId || undefined,
          language,
          code,
          problemTitle: activeProblem?.title,
          problemPrompt: activeProblem?.prompt,
          durationSeconds: Math.max(
            120,
            Math.round((Date.now() - sessionStart.current) / 1000),
          ),
        }),
      });
      const data = await response.json();
      if (!data.success) throw new Error(data.error ?? "Evaluation failed.");
      setResult(data.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Evaluation failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-4xl space-y-6 px-4 py-8">
      <div>
        <p className="text-xs font-bold uppercase tracking-[0.2em] text-amber-600">
          Six · Hands-on Practice
        </p>
        <h1 className="mt-1 text-3xl font-black text-stone-900">CS Code Lab</h1>
        <p className="mt-2 text-stone-600">
          Solve problems in the editor, submit for AI feedback, and build application mastery.
        </p>
      </div>

      {courseId && selectedCourse ? (
        <StudyLoopStrip
          courseId={courseId}
          courseTitle={selectedCourse.title}
          topics={selectedCourse.topics ?? []}
          focusTopic={focusTopic}
        />
      ) : null}

      <div className="grid gap-4 md:grid-cols-[1fr_16rem]">
        <div className="space-y-4">
          <div className="rounded-2xl border border-orange-100 bg-white p-5">
            <p className="font-bold text-stone-900">{activeProblem?.title}</p>
            <p className="mt-2 text-sm text-stone-600">{activeProblem?.prompt}</p>
          </div>

          <div className="overflow-hidden rounded-2xl border border-stone-800 bg-stone-950">
            <div className="border-b border-stone-800 px-3 py-2 text-xs text-stone-400">
              {language}
            </div>
            <textarea
              value={code}
              onChange={(event) => setCode(event.target.value)}
              spellCheck={false}
              className="min-h-[320px] w-full resize-y bg-transparent p-4 font-mono text-sm leading-relaxed text-emerald-300 outline-none"
            />
          </div>

          <button
            type="button"
            onClick={() => void evaluate()}
            disabled={loading}
            className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-amber-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-amber-500 disabled:opacity-60 touch-manipulation"
          >
            {loading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Sparkles className="h-4 w-4" />
            )}
            Submit for review
          </button>

          {error ? (
            <p className="rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
              {error}
            </p>
          ) : null}
        </div>

        <aside className="space-y-4">
          <div className="rounded-2xl border border-orange-100 bg-white p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-stone-500">
              Language
            </p>
            <select
              value={language}
              onChange={(event) => setLanguage(event.target.value)}
              className="mt-2 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
            >
              {problems.map((problem) => (
                <option key={problem.language} value={problem.language}>
                  {problem.language}
                </option>
              ))}
            </select>
          </div>

          <div className="rounded-2xl border border-orange-100 bg-white p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-stone-500">
              Course context
            </p>
            <select
              value={courseId}
              onChange={(event) => setCourseId(event.target.value)}
              className="mt-2 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
            >
              <option value="">No course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>
          </div>

          <Link
            href={luckyQuizHref(courseId || null, null, selectedCourse?.topics?.[0] ?? null)}
            className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-violet-200 bg-violet-50 px-4 py-3 text-sm font-semibold text-violet-800 hover:bg-violet-100 touch-manipulation"
          >
            <Play className="h-4 w-4" /> Practice quiz instead
          </Link>
        </aside>
      </div>

      {result ? (
        <div className="space-y-4 rounded-3xl border border-amber-200 bg-gradient-to-br from-amber-50 to-white p-6">
          <div className="text-center">
            <p className="text-sm font-bold uppercase tracking-wider text-amber-700">
              Application score
            </p>
            <p className="text-4xl font-black text-stone-900">{result.score}%</p>
            <p className="mt-2 text-stone-600">{result.summary}</p>
          </div>
          <DetailBlock title="Correctness" body={result.correctness} />
          <DetailBlock title="Complexity" body={result.complexity} />
          {result.edgeCases.length > 0 ? (
            <ListBlock title="Edge cases" items={result.edgeCases} />
          ) : null}
          {result.improvements.length > 0 ? (
            <ListBlock title="Improvements" items={result.improvements} />
          ) : null}
          {courseId && selectedCourse ? (
            <div
              data-hub-chrome
              className="rounded-2xl border border-violet-200 bg-white p-4"
            >
              <p className="text-sm font-bold text-stone-900">Keep the loop going</p>
              <p className="mt-1 text-sm text-stone-600">
                Drill application gaps in Lucky or re-chunk the concept in Six.
              </p>
              <div className="mt-3 flex flex-wrap gap-2">
                <Link
                  href={luckyQuizHref(
                    courseId,
                    null,
                    selectedCourse.topics?.[0] ?? activeProblem?.title ?? null,
                  )}
                  className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-violet-500 touch-manipulation"
                >
                  <Play className="h-4 w-4" />
                  Lucky quiz
                </Link>
                <Link
                  href={sixChunkingHref(
                    courseId,
                    selectedCourse.topics?.[0] ?? activeProblem?.title ?? "notes",
                  )}
                  className="inline-flex min-h-11 items-center rounded-xl border border-teal-300 bg-teal-50 px-4 py-2.5 text-sm font-bold text-teal-900 hover:bg-teal-100 touch-manipulation"
                >
                  Six chunking
                </Link>
              </div>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

function DetailBlock({ title, body }: { title: string; body: string }) {
  return (
    <div className="rounded-xl border border-amber-100 bg-white/80 p-4">
      <p className="font-semibold text-stone-900">{title}</p>
      <p className="mt-1 text-sm text-stone-700">{body}</p>
    </div>
  );
}

function ListBlock({ title, items }: { title: string; items: string[] }) {
  return (
    <div className="rounded-xl border border-amber-100 bg-white/80 p-4">
      <p className="font-semibold text-stone-900">{title}</p>
      <ul className="mt-2 list-inside list-disc space-y-1 text-sm text-stone-700">
        {items.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Loader2 } from "lucide-react";

type PackOption = {
  id: string;
  subject: string;
  concepts: Array<{ id: string; title: string }>;
};

type CourseOption = {
  id: string;
  title: string;
  topics: string[];
};

/** Merge query into continueHrefBase without dropping challengeId etc. */
function withContinueParams(
  continueHrefBase: string,
  extra: Record<string, string>,
): string {
  const [pathPart, existingQs = ""] = continueHrefBase.split("?");
  const params = new URLSearchParams(existingQs);
  for (const [key, value] of Object.entries(extra)) {
    if (value) params.set(key, value);
  }
  const qs = params.toString();
  return qs ? `${pathPart}?${qs}` : pathPart!;
}

/**
 * Bundle K — Concept-less entry: Choose subject → topic → start activity.
 * Never shows internal conceptId errors to learners.
 */
export function ConceptEntryPicker({
  activityKind,
  activityLabel,
  continueHrefBase,
}: {
  activityKind: string;
  activityLabel: string;
  /** Base path e.g. /study/activities/coding — conceptId appended on start */
  continueHrefBase: string;
}) {
  const router = useRouter();
  const [packs, setPacks] = useState<PackOption[]>([]);
  const [courses, setCourses] = useState<CourseOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [starting, setStarting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mode, setMode] = useState<"library" | "course">("library");
  const [packId, setPackId] = useState("");
  const [klConceptId, setKlConceptId] = useState("");
  const [courseId, setCourseId] = useState("");
  const [topic, setTopic] = useState("");

  useEffect(() => {
    let cancelled = false;
    async function load() {
      setLoading(true);
      try {
        const [libRes, courseRes] = await Promise.all([
          fetch("/api/study/capability-topics", { credentials: "same-origin" }),
          fetch("/api/courses", { credentials: "same-origin" }),
        ]);
        const libData = await libRes.json();
        const courseData = await courseRes.json();
        if (!cancelled) {
          if (libData.success) setPacks(libData.data ?? []);
          if (courseData.success || courseData.courses) {
            setCourses(
              (courseData.courses ?? []).map(
                (c: { id: string; title: string; topics?: string[] }) => ({
                  id: c.id,
                  title: c.title,
                  topics: c.topics ?? [],
                }),
              ),
            );
          }
        }
      } catch {
        if (!cancelled) setError("Could not load topics.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  const selectedPack = useMemo(
    () => packs.find((p) => p.id === packId) ?? null,
    [packs, packId],
  );
  const selectedCourse = useMemo(
    () => courses.find((c) => c.id === courseId) ?? null,
    [courses, courseId],
  );

  async function startFromLibrary() {
    if (!klConceptId) {
      setError("Choose a topic to continue.");
      return;
    }
    setStarting(true);
    setError(null);
    try {
      const res = await fetch("/api/study/ensure-concept", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({ klConceptId }),
      });
      const data = await res.json();
      if (!data.success) {
        throw new Error(data.error ?? "Could not start.");
      }
      const conceptId = data.data.conceptId as string;
      router.push(
        withContinueParams(continueHrefBase, {
          conceptId,
          klConceptId,
        }),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not start.");
    } finally {
      setStarting(false);
    }
  }

  function startFromCourse() {
    if (!courseId || !topic.trim()) {
      setError("Choose a class and topic to continue.");
      return;
    }
    router.push(
      withContinueParams(continueHrefBase, {
        courseId,
        topic: topic.trim(),
      }),
    );
  }

  if (loading) {
    return (
      <div
        className="flex min-h-[40vh] items-center justify-center text-stone-500"
        data-concept-entry-picker
      >
        <Loader2 className="h-6 w-6 animate-spin" aria-label="Loading topics" />
      </div>
    );
  }

  return (
    <div
      className="mx-auto grid max-w-5xl gap-6 px-4 py-10 lg:grid-cols-[minmax(0,14rem)_1fr]"
      data-concept-entry-picker
      data-activity-kind={activityKind}
    >
      <aside className="space-y-3">
        <p className="text-xs font-bold uppercase tracking-wider text-teal-700">
          Get ready
        </p>
        <h1 className="text-2xl font-bold text-stone-900">{activityLabel}</h1>
        <p className="text-sm text-stone-600">
          Choose a subject and topic, then start. You don’t need Adaptive first.
        </p>
        <div className="flex flex-col gap-2 pt-2">
          <button
            type="button"
            onClick={() => setMode("library")}
            className={`min-h-11 rounded-xl px-3 py-2 text-left text-sm font-semibold touch-manipulation ${
              mode === "library"
                ? "bg-stone-900 text-white"
                : "border border-stone-200 bg-white text-stone-800"
            }`}
          >
            Study library topics
          </button>
          <button
            type="button"
            onClick={() => setMode("course")}
            className={`min-h-11 rounded-xl px-3 py-2 text-left text-sm font-semibold touch-manipulation ${
              mode === "course"
                ? "bg-stone-900 text-white"
                : "border border-stone-200 bg-white text-stone-800"
            }`}
          >
            My classes
          </button>
        </div>
      </aside>

      <section className="rounded-2xl border border-stone-200 bg-white p-5 shadow-sm">
        {mode === "library" ? (
          <div className="space-y-4">
            <label className="block text-sm font-medium text-stone-700">
              Subject
              <select
                className="mt-1 w-full rounded-xl border border-stone-200 px-3 py-2.5"
                value={packId}
                onChange={(e) => {
                  setPackId(e.target.value);
                  setKlConceptId("");
                }}
              >
                <option value="">Choose a subject…</option>
                {packs.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.subject}
                  </option>
                ))}
              </select>
            </label>
            <label className="block text-sm font-medium text-stone-700">
              Topic
              <select
                className="mt-1 w-full rounded-xl border border-stone-200 px-3 py-2.5"
                value={klConceptId}
                disabled={!selectedPack}
                onChange={(e) => setKlConceptId(e.target.value)}
              >
                <option value="">Choose a topic…</option>
                {(selectedPack?.concepts ?? []).map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.title}
                  </option>
                ))}
              </select>
            </label>
            <button
              type="button"
              disabled={starting || !klConceptId}
              onClick={() => void startFromLibrary()}
              className="inline-flex min-h-11 items-center justify-center rounded-xl bg-teal-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-teal-800 disabled:opacity-50 touch-manipulation"
            >
              {starting ? "Starting…" : `Start ${activityLabel}`}
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {courses.length === 0 ? (
              <p className="text-sm text-stone-600">
                No classes yet. Use study library topics, or{" "}
                <a href="/courses" className="font-semibold text-teal-700 underline">
                  add a class
                </a>
                .
              </p>
            ) : (
              <>
                <label className="block text-sm font-medium text-stone-700">
                  Class
                  <select
                    className="mt-1 w-full rounded-xl border border-stone-200 px-3 py-2.5"
                    value={courseId}
                    onChange={(e) => {
                      setCourseId(e.target.value);
                      setTopic("");
                    }}
                  >
                    <option value="">Choose a class…</option>
                    {courses.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.title}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="block text-sm font-medium text-stone-700">
                  Topic
                  <select
                    className="mt-1 w-full rounded-xl border border-stone-200 px-3 py-2.5"
                    value={topic}
                    disabled={!selectedCourse}
                    onChange={(e) => setTopic(e.target.value)}
                  >
                    <option value="">Choose a topic…</option>
                    {(selectedCourse?.topics ?? []).map((t) => (
                      <option key={t} value={t}>
                        {t}
                      </option>
                    ))}
                  </select>
                </label>
                <button
                  type="button"
                  disabled={!courseId || !topic.trim()}
                  onClick={startFromCourse}
                  className="inline-flex min-h-11 items-center justify-center rounded-xl bg-teal-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-teal-800 disabled:opacity-50 touch-manipulation"
                >
                  Start {activityLabel}
                </button>
              </>
            )}
          </div>
        )}
        {error ? <p className="mt-3 text-sm text-rose-700">{error}</p> : null}
      </section>
    </div>
  );
}

