"use client";

import {
  useCallback,
  useRef,
  type MouseEvent,
  type PointerEvent,
  type TouchEvent,
} from "react";

export type TapHandlerProps = {
  onClick: (event: MouseEvent<HTMLElement>) => void;
  onPointerDown: (event: PointerEvent<HTMLElement>) => void;
  onPointerUp: (event: PointerEvent<HTMLElement>) => void;
  onPointerCancel: (event: PointerEvent<HTMLElement>) => void;
  onTouchStart: (event: TouchEvent<HTMLElement>) => void;
  onTouchEnd: (event: TouchEvent<HTMLElement>) => void;
  /** Marks chrome for CSS hit-testing (children get pointer-events: none). */
  "data-tap-handler": "1";
};

/**
 * Reliable taps on iPad/Safari — same constraints GoodNotes avoids by being
 * native, and that web note apps hit constantly:
 *
 * - iOS often cancels Pointer Events mid-gesture (`pointercancel`) so
 *   `pointerup` never arrives.
 * - Real `<a href>` navigation (Shelf) still works; buttons need an explicit
 *   `touchend` activation path.
 * - Mouse/keyboard still use `click`.
 *
 * Fire order: touchend (finger) → pointerup (pen, if no touchend) → click.
 * 450ms debounce collapses duplicates / ghost clicks.
 */
export function useTapHandler(handler: () => void): TapHandlerProps {
  const handlerRef = useRef(handler);
  handlerRef.current = handler;
  const lastFireRef = useRef(0);
  const startRef = useRef<{ x: number; y: number } | null>(null);
  const armedRef = useRef(false);
  /** True after touchend handled this gesture — skip redundant pointerup. */
  const touchHandledRef = useRef(false);

  const fire = useCallback(() => {
    const win = window as Window & { __coreOverlayLastFire?: number };
    const now = Date.now();
    // Debounce only our own fires. Do NOT bail on __coreOverlayLastFire set by a
    // document overlay before btn.click() — that deadlock made panel interiors
    // open-but-dead on iPad (overlay stamped, then click → fire no-op'd).
    if (now - lastFireRef.current < 450) return;
    lastFireRef.current = now;
    win.__coreOverlayLastFire = now;
    handlerRef.current();
  }, []);

  const startAt = useCallback((x: number, y: number) => {
    startRef.current = { x, y };
    armedRef.current = true;
    touchHandledRef.current = false;
  }, []);

  const movedTooFar = useCallback((x: number, y: number) => {
    const start = startRef.current;
    if (!start) return false;
    return Math.abs(x - start.x) > 22 || Math.abs(y - start.y) > 22;
  }, []);

  const onPointerDown = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      if (event.pointerType === "mouse") return;
      startAt(event.clientX, event.clientY);
    },
    [startAt],
  );

  const onTouchStart = useCallback(
    (event: TouchEvent<HTMLElement>) => {
      const t = event.changedTouches[0] ?? event.touches[0];
      if (!t) return;
      startAt(t.clientX, t.clientY);
    },
    [startAt],
  );

  const onTouchEnd = useCallback(
    (event: TouchEvent<HTMLElement>) => {
      const t = event.changedTouches[0];
      if (!t || !armedRef.current) return;
      armedRef.current = false;
      if (movedTooFar(t.clientX, t.clientY)) {
        startRef.current = null;
        return;
      }
      startRef.current = null;
      touchHandledRef.current = true;
      // Stop iOS ghost click; we already activated.
      event.preventDefault();
      event.stopPropagation();
      fire();
    },
    [fire, movedTooFar],
  );

  const onPointerUp = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      if (event.pointerType === "mouse") return;
      if (typeof event.button === "number" && event.button > 0) return;
      // Finger already handled via touchend (more reliable than pointerup on iOS).
      if (event.pointerType === "touch" || touchHandledRef.current) {
        touchHandledRef.current = false;
        return;
      }
      if (!armedRef.current) return;
      armedRef.current = false;
      if (movedTooFar(event.clientX, event.clientY)) {
        startRef.current = null;
        return;
      }
      startRef.current = null;
      event.preventDefault();
      event.stopPropagation();
      fire();
    },
    [fire, movedTooFar],
  );

  const onPointerCancel = useCallback(() => {
    // iOS Scribble / scroll often cancels pointers — clear arm so we don't
    // fire a stale tap later; touchend may still arrive and activate.
    armedRef.current = false;
    startRef.current = null;
  }, []);

  const onClick = useCallback(
    (event: MouseEvent<HTMLElement>) => {
      // Keyboard activation and mouse; touch already fired via touchend.
      fire();
      event.preventDefault();
    },
    [fire],
  );

  return {
    onClick,
    onPointerDown,
    onPointerUp,
    onPointerCancel,
    onTouchStart,
    onTouchEnd,
    "data-tap-handler": "1",
  };
}

import type { AIProviderName } from "./config";
import { GeminiProvider } from "./providers/gemini";
import { GroqProvider, tryCreateGroqProvider } from "./providers/groq";
import {
  OpenRouterProvider,
  tryCreateOpenRouterProvider,
} from "./providers/openrouter";
import { OpenAIProvider } from "./providers/openai";
import type { AIServiceProvider } from "./types";

export function tryCreateGeminiProvider(): GeminiProvider | null {
  try {
    return new GeminiProvider();
  } catch {
    return null;
  }
}

export function tryCreateOpenAIProvider(): OpenAIProvider | null {
  try {
    return new OpenAIProvider();
  } catch {
    return null;
  }
}

export function createAIProvider(name: AIProviderName): AIServiceProvider | null {
  switch (name) {
    case "gemini":
      return tryCreateGeminiProvider();
    case "groq":
      return tryCreateGroqProvider();
    case "openrouter":
      return tryCreateOpenRouterProvider();
    case "openai":
      return tryCreateOpenAIProvider();
    default:
      return null;
  }
}

export function buildConfiguredAIProviders(
  chain: AIProviderName[],
): AIServiceProvider[] {
  const providers: AIServiceProvider[] = [];
  const seen = new Set<string>();

  for (const name of chain) {
    if (seen.has(name)) continue;
    seen.add(name);

    const provider = createAIProvider(name);
    if (provider) providers.push(provider);
  }

  return providers;
}

import { triggerGoogleSyncIfStale } from "@/lib/calendar/google-background-sync";
import { triggerLmsSyncIfStale } from "@/lib/lms/background-sync";
import type { WorkspaceCalendarItem, WorkspaceCourse } from "@/lib/calendar/workspace-types";

export interface GoogleConnectionStatus {
  id: string;
  calendarName: string | null;
  externalCalendarId: string;
  color: string | null;
  status: string;
  lastSyncedAt: string | null;
}

function fetchWithTimeout(
  input: RequestInfo | URL,
  init?: RequestInit & { timeoutMs?: number },
): Promise<Response> {
  const timeoutMs = init?.timeoutMs ?? 12_000;
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), timeoutMs);
  const { timeoutMs: _drop, signal: externalSignal, ...rest } = init ?? {};

  return fetch(input, {
    credentials: "same-origin",
    ...rest,
    signal: externalSignal ?? controller.signal,
  }).finally(() => window.clearTimeout(timer));
}

/**
 * Google + LMS sync after the calendar grid is already visible.
 * Never throws — failures are logged only in dev.
 */
export async function runCalendarBackgroundSync(options: {
  params: URLSearchParams;
  onData?: (data: {
    items: WorkspaceCalendarItem[];
    courses: WorkspaceCourse[];
  }) => void;
  onGoogleConnections?: (connections: GoogleConnectionStatus[]) => void;
}): Promise<void> {
  try {
    let shouldRefresh = false;

    const googleResponse = await fetchWithTimeout("/api/calendar/google/status", {
      timeoutMs: 8_000,
    }).catch(() => null);
    const googleJson = googleResponse ? await googleResponse.json() : { success: false };

    if (googleJson.success) {
      const connections = (googleJson.connections ?? []) as GoogleConnectionStatus[];
      options.onGoogleConnections?.(
        connections.filter((connection) => connection.status === "connected"),
      );
      if (await triggerGoogleSyncIfStale(connections)) {
        shouldRefresh = true;
      }
    }

    const lmsResponse = await fetchWithTimeout("/api/lms/connect", {
      timeoutMs: 8_000,
    }).catch(() => null);
    const lmsJson = lmsResponse ? await lmsResponse.json() : { success: false };

    if (lmsJson.success) {
      if (await triggerLmsSyncIfStale(lmsJson.connections ?? [])) {
        shouldRefresh = true;
      }
    }

    if (!shouldRefresh || !options.onData) return;

    const refresh = await fetchWithTimeout(`/api/calendar?${options.params}`, {
      timeoutMs: 15_000,
    });
    const refreshJson = await refresh.json();
    if (refreshJson.success) {
      options.onData({
        items: refreshJson.data.items as WorkspaceCalendarItem[],
        courses: refreshJson.data.courses as WorkspaceCourse[],
      });
    }
  } catch {
    // Background sync must never block or break the calendar UI.
  }
}

