export function getPaletteForScale(scale: ColorScaleId): readonly string[] {
  return COLOR_SCALES[scale]?.colors ?? COLOR_SCALES.vivid.colors;
}

function hexToRgb(hex: string): [number, number, number] | null {
  const normalized = hex.replace("#", "");
  if (normalized.length !== 6) return null;
  return [
    parseInt(normalized.slice(0, 2), 16),
    parseInt(normalized.slice(2, 4), 16),
    parseInt(normalized.slice(4, 6), 16),
  ];
}

function rgbToHex(r: number, g: number, b: number): string {
  return `#${[r, g, b].map((v) => Math.round(v).toString(16).padStart(2, "0")).join("")}`;
}

function nearestPaletteColor(hex: string, palette: readonly string[]): string {
  const rgb = hexToRgb(hex);
  if (!rgb) return palette[0] ?? hex;

  let best = palette[0] ?? hex;
  let bestDist = Number.POSITIVE_INFINITY;

  for (const candidate of palette) {
    const c = hexToRgb(candidate);
    if (!c) continue;
    const dist =
      (rgb[0] - c[0]) ** 2 + (rgb[1] - c[1]) ** 2 + (rgb[2] - c[2]) ** 2;
    if (dist < bestDist) {
      bestDist = dist;
      best = candidate;
    }
  }

  return best;
}

/** Map a stored color onto the active event palette. */
export function applyToEventPalette(hex: string, palette: readonly string[]): string {
  return nearestPaletteColor(hex, palette);
}

/** Map a stored color onto the active palette (Google-style calendar recoloring). */
export function applyColorScale(hex: string, scale: ColorScaleId): string {
  const palette = getPaletteForScale(scale);
  return nearestPaletteColor(hex, palette);
}

import {
  occurrenceKey,
  parseRecurrenceRule,
  serializeRecurrenceRule,
  type RecurrenceEditScope,
  type RecurrenceException,
  type RecurrenceRule,
} from "@/lib/calendar/recurrence";

export type { RecurrenceEditScope };

export interface RecurrenceEventRecord {
  id: string;
  userId: string;
  title: string;
  description: string | null;
  startAt: Date;
  endAt: Date | null;
  allDay: boolean;
  eventType: string;
  color: string | null;
  priority: string;
  recurrence: string | null;
  reminderAt: Date | null;
  completed: boolean;
  location: string | null;
  courseId: string | null;
  assignmentId?: string | null;
  externalId?: string | null;
  externalSource?: string | null;
  calendarConnectionId?: string | null;
}

export interface RecurrenceEventPatch {
  title?: string;
  description?: string | null;
  startAt?: Date;
  endAt?: Date | null;
  allDay?: boolean;
  eventType?: string;
  color?: string | null;
  priority?: string;
  recurrence?: string | null;
  reminderAt?: Date | null;
  completed?: boolean;
  location?: string | null;
  courseId?: string | null;
}

export interface RecurrenceMutationResult {
  masterData: Record<string, unknown>;
  createEvent?: Record<string, unknown>;
  deleteSeries?: boolean;
}

export function parseOccurrenceItemId(
  id: string,
): { seriesId: string; occurrenceAt: Date } | null {
  const match = id.match(/^evt-(.+)-(\d{13})$/);
  if (!match?.[1] || !match[2]) return null;
  return {
    seriesId: match[1],
    occurrenceAt: new Date(Number(match[2])),
  };
}

function dayBefore(date: Date): Date {
  const result = new Date(date);
  result.setDate(result.getDate() - 1);
  result.setHours(23, 59, 59, 999);
  return result;
}

function setRuleUntil(rule: RecurrenceRule, until: Date): RecurrenceRule {
  const next: RecurrenceRule = { ...rule, until: until.toISOString() };
  delete next.count;
  return next;
}

function baseRuleWithoutMeta(rule: RecurrenceRule): RecurrenceRule {
  const { exceptions: _exceptions, until: _until, count: _count, ...base } = rule;
  return base;
}

function upsertException(
  exceptions: RecurrenceException[],
  occurrenceAt: Date,
  patch: Partial<RecurrenceException>,
): RecurrenceException[] {
  const key = occurrenceKey(occurrenceAt);
  const index = exceptions.findIndex((item) => item.occurrenceAt === key);
  const current = index >= 0 ? exceptions[index] : { occurrenceAt: key };
  const next: RecurrenceException = {
    ...current,
    ...patch,
    occurrenceAt: key,
    override: patch.override
      ? { ...current.override, ...patch.override }
      : current.override,
  };

  if (index >= 0) {
    const copy = [...exceptions];
    copy[index] = next;
    return copy;
  }

  return [...exceptions, next];
}

function buildOverrideFromPatch(
  existing: RecurrenceEventRecord,
  updates: RecurrenceEventPatch,
): RecurrenceException["override"] {
  const override: NonNullable<RecurrenceException["override"]> = {};

  if (updates.title !== undefined) override.title = updates.title;
  if (updates.description !== undefined) override.description = updates.description;
  if (updates.startAt !== undefined) override.startAt = updates.startAt.toISOString();
  if (updates.endAt !== undefined) {
    override.endAt = updates.endAt ? updates.endAt.toISOString() : null;
  }
  if (updates.allDay !== undefined) override.allDay = updates.allDay;
  if (updates.location !== undefined) override.location = updates.location;
  if (updates.color !== undefined) override.color = updates.color;
  if (updates.completed !== undefined) override.completed = updates.completed;

  if (Object.keys(override).length === 0) {
    return {
      title: existing.title,
      description: existing.description,
      startAt: existing.startAt.toISOString(),
      endAt: existing.endAt?.toISOString() ?? null,
      allDay: existing.allDay,
      location: existing.location,
      color: existing.color,
      completed: existing.completed,
    };
  }

  return override;
}

function copyEventForFollowUp(
  existing: RecurrenceEventRecord,
  updates: RecurrenceEventPatch,
  occurrenceAt: Date,
  rule: RecurrenceRule,
) {
  const startAt = updates.startAt ?? occurrenceAt;
  const duration = existing.endAt
    ? existing.endAt.getTime() - existing.startAt.getTime()
    : existing.allDay
      ? 24 * 60 * 60 * 1000 - 1
      : 60 * 60 * 1000;
  const endAt =
    updates.endAt ??
    (updates.startAt ? new Date(startAt.getTime() + duration) : existing.endAt);

  return {
    userId: existing.userId,
    courseId: updates.courseId !== undefined ? updates.courseId : existing.courseId,
    title: updates.title ?? existing.title,
    description:
      updates.description !== undefined ? updates.description : existing.description,
    startAt,
    endAt,
    allDay: updates.allDay ?? existing.allDay,
    eventType: updates.eventType ?? existing.eventType,
    color: updates.color !== undefined ? updates.color : existing.color,
    priority: updates.priority ?? existing.priority,
    recurrence: serializeRecurrenceRule(baseRuleWithoutMeta(rule)),
    reminderAt:
      updates.reminderAt !== undefined ? updates.reminderAt : existing.reminderAt,
    completed: updates.completed ?? existing.completed,
    location: updates.location !== undefined ? updates.location : existing.location,
    externalSource: null,
    externalId: null,
    calendarConnectionId: null,
  };
}

export function applyRecurrenceEventUpdate(
  existing: RecurrenceEventRecord,
  occurrenceAt: Date | null,
  scope: RecurrenceEditScope,
  updates: RecurrenceEventPatch,
): RecurrenceMutationResult {
  const rule = parseRecurrenceRule(existing.recurrence);

  if (!rule || !occurrenceAt || scope === "series") {
    const masterData: Record<string, unknown> = {};
    if (updates.title !== undefined) masterData.title = updates.title;
    if (updates.description !== undefined) masterData.description = updates.description;
    if (updates.startAt !== undefined) masterData.startAt = updates.startAt;
    if (updates.endAt !== undefined) masterData.endAt = updates.endAt;
    if (updates.allDay !== undefined) masterData.allDay = updates.allDay;
    if (updates.eventType !== undefined) masterData.eventType = updates.eventType;
    if (updates.color !== undefined) masterData.color = updates.color;
    if (updates.priority !== undefined) masterData.priority = updates.priority;
    if (updates.recurrence !== undefined) masterData.recurrence = updates.recurrence;
    if (updates.reminderAt !== undefined) masterData.reminderAt = updates.reminderAt;
    if (updates.completed !== undefined) masterData.completed = updates.completed;
    if (updates.location !== undefined) masterData.location = updates.location;
    if (updates.courseId !== undefined) masterData.courseId = updates.courseId;
    return { masterData };
  }

  if (scope === "single") {
    const exceptions = upsertException(rule.exceptions ?? [], occurrenceAt, {
      override: buildOverrideFromPatch(existing, updates),
    });

    return {
      masterData: {
        recurrence: serializeRecurrenceRule({ ...rule, exceptions }),
      },
    };
  }

  const truncatedRule = setRuleUntil(rule, dayBefore(occurrenceAt));
  return {
    masterData: {
      recurrence: serializeRecurrenceRule(truncatedRule),
    },
    createEvent: copyEventForFollowUp(existing, updates, occurrenceAt, rule),
  };
}

export function applyRecurrenceEventDelete(
  existing: RecurrenceEventRecord,
  occurrenceAt: Date | null,
  scope: RecurrenceEditScope,
): RecurrenceMutationResult {
  const rule = parseRecurrenceRule(existing.recurrence);

  if (!rule || !occurrenceAt || scope === "series") {
    return { masterData: {}, deleteSeries: true };
  }

  if (scope === "single") {
    const exceptions = upsertException(rule.exceptions ?? [], occurrenceAt, {
      cancelled: true,
    });
    return {
      masterData: {
        recurrence: serializeRecurrenceRule({ ...rule, exceptions }),
      },
    };
  }

  return {
    masterData: {
      recurrence: serializeRecurrenceRule(setRuleUntil(rule, dayBefore(occurrenceAt))),
    },
  };
}

import type { NoteMethod } from "@/generated/prisma";

import {
  CORE_FORMAT_CATALOG,
  getFormatDefinition,
  type CoreFormatId,
} from "@/lib/core/format-catalog";
import {
  emptyConcepts,
  emptyFlow,
  emptyMindMap,
  emptyOutlineNodes,
  emptyProblemSolution,
  emptyProgressive,
  emptyTimeline,
  emptyTwoColumn,
  type FormatRecommendation,
  type NoteDocument,
} from "@/lib/core/note-types";

export interface FormatAnalysis {
  recommendations: FormatRecommendation[];
  materialType: string;
  summary: string;
  suggestedTitle?: string;
}

function scoreFormat(
  formatId: CoreFormatId,
  text: string,
  courseTitle: string,
): { score: number; reason: string } {
  const def = getFormatDefinition(formatId);
  const haystack = `${courseTitle} ${text}`.toLowerCase();
  let score = 0;
  const hits: string[] = [];

  for (const word of def.signalWords ?? []) {
    if (haystack.includes(word.toLowerCase())) {
      score += 12;
      hits.push(word);
    }
  }

  if (formatId === "PROGRESSIVE" || formatId === "PROBLEM_SOLUTION") {
    if (/\b(function|class|def |const |import |algorithm|code|debug)\b/i.test(haystack)) {
      score += 25;
    }
    if (/\b(homework|exercise|problem set|leetcode)\b/i.test(haystack)) {
      score += 18;
    }
  }

  if (formatId === "TIMELINE" || formatId === "OUTLINE") {
    if (/\b(\d{4}|century|war|revolution|dynasty|era|bce|ad)\b/i.test(haystack)) {
      score += 20;
    }
  }

  if (formatId === "MIND_MAP" || formatId === "CONCEPT_DEFINITION") {
    if (/\b(cell|organism|pathway|system|anatomy|physiology|ecosystem)\b/i.test(haystack)) {
      score += 22;
    }
    if (/\b(psychology|behavior|cognitive|disorder|therapy)\b/i.test(haystack)) {
      score += 18;
    }
  }

  if (formatId === "PROCESS_FLOW" || formatId === "FLOW") {
    if (/\b(process|cycle|reaction|mechanism|phase|step \d)\b/i.test(haystack)) {
      score += 20;
    }
  }

  if (formatId === "COMPARISON_MATRIX" || formatId === "CHARTING") {
    if (/\b(compare|contrast|versus|vs\.|similarit|differen)\b/i.test(haystack)) {
      score += 22;
    }
  }

  if (formatId === "CORNELL" || formatId === "SENTENCE") {
    if (/\b(lecture|slides|chapter \d|unit \d)\b/i.test(haystack)) {
      score += 10;
    }
  }

  const reason =
    hits.length > 0
      ? `Matches keywords: ${hits.slice(0, 3).join(", ")}`
      : score > 0
        ? `Fits the type of material in ${courseTitle || "this course"}`
        : "General-purpose format";

  return { score, reason };
}

/** Heuristic recommendations from source text — no AI required. */
export function recommendFormatsHeuristic(
  sourceText: string,
  courseTitle = "",
  limit = 4,
): FormatAnalysis {
  const text = sourceText.trim();
  const materialType = detectMaterialType(text, courseTitle);

  const scored = CORE_FORMAT_CATALOG.filter(
    (format) => !["BLANK", "DOT_GRID", "RULED"].includes(format.id),
  )
    .map((format) => {
      const { score, reason } = scoreFormat(format.id, text, courseTitle);
      return {
        formatId: format.id,
        confidence: Math.min(0.95, 0.35 + score / 100),
        reason,
        raw: score,
      };
    })
    .filter((item) => item.raw > 0)
    .sort((a, b) => b.raw - a.raw)
    .slice(0, limit);

  const recommendations: FormatRecommendation[] =
    scored.length > 0
      ? scored.map(({ formatId, confidence, reason }) => ({
          formatId,
          confidence,
          reason,
        }))
      : [
          {
            formatId: "OUTLINE",
            confidence: 0.5,
            reason: "Flexible starting point for any subject",
          },
          {
            formatId: "CORNELL",
            confidence: 0.45,
            reason: "Works well for lectures and readings",
          },
        ];

  return {
    recommendations,
    materialType,
    summary: summarizeMaterial(text, courseTitle, materialType),
  };
}

function detectMaterialType(text: string, courseTitle: string): string {
  const haystack = `${courseTitle} ${text}`.toLowerCase();
  if (/\b(function|class |algorithm|programming|code)\b/.test(haystack)) return "programming";
  if (/\b(theorem|equation|integral|derivative|proof)\b/.test(haystack)) return "mathematics";
  if (/\b(war|century|revolution|dynasty|treaty)\b/.test(haystack)) return "history";
  if (/\b(cell|organism|dna|protein|anatomy|physiology)\b/.test(haystack)) return "biology";
  if (/\b(psychology|behavior|cognitive|disorder)\b/.test(haystack)) return "psychology";
  if (/\b(theorem|complexity|graph theory|data structure)\b/.test(haystack)) return "cs_theory";
  if (text.length < 200) return "general";
  return "lecture_notes";
}

function summarizeMaterial(text: string, courseTitle: string, materialType: string): string {
  const preview = text.replace(/\s+/g, " ").trim().slice(0, 180);
  const subject = courseTitle || materialType.replace(/_/g, " ");
  return preview
    ? `${subject}: ${preview}${text.length > 180 ? "…" : ""}`
    : `Start capturing knowledge for ${subject}.`;
}

export function resolveActiveFormat(doc: NoteDocument, method: NoteMethod): CoreFormatId {
  if (doc.metadata?.activeFormat) return doc.metadata.activeFormat;
  const match = CORE_FORMAT_CATALOG.find((format) => format.noteMethod === method);
  return match?.id ?? "BLANK";
}

export function applyFormatToDocument(
  doc: NoteDocument,
  formatId: CoreFormatId,
  options?: { preserveContent?: boolean },
): { doc: NoteDocument; method: NoteMethod } {
  const def = getFormatDefinition(formatId);
  const preserve = options?.preserveContent !== false;
  const next: NoteDocument = preserve
    ? { ...doc }
  : { ...emptyDocumentFrom(doc) };

  next.metadata = {
    ...next.metadata,
    activeFormat: formatId,
    appliedFormats: [...new Set([...(next.metadata?.appliedFormats ?? []), formatId])],
  };

  if (!preserve || isDocumentMostlyEmpty(next)) {
    seedFormatStructure(next, formatId);
  }

  return { doc: next, method: def.noteMethod };
}

function emptyDocumentFrom(doc: NoteDocument): NoteDocument {
  return {
    ...doc,
    typed: "",
    metadata: { ...doc.metadata, activeFormat: doc.metadata?.activeFormat },
  };
}

function isDocumentMostlyEmpty(doc: NoteDocument): boolean {
  return (
    !doc.typed.trim() &&
    !doc.cornell?.notes?.trim() &&
    (doc.qa?.pairs.every((p) => !p.question && !p.answer) ?? true) &&
    (doc.timeline?.events.every((e) => !e.title) ?? true)
  );
}

function seedFormatStructure(doc: NoteDocument, formatId: CoreFormatId): void {
  switch (formatId) {
    case "PROGRESSIVE":
      doc.progressive = emptyProgressive();
      break;
    case "PROBLEM_SOLUTION":
      doc.problemSolution = emptyProblemSolution();
      break;
    case "CONCEPT_DEFINITION":
      doc.concepts = emptyConcepts();
      break;
    case "TIMELINE":
      doc.timeline = emptyTimeline();
      break;
    case "TWO_COLUMN":
    case "BOXING":
      doc.twoColumn = emptyTwoColumn();
      break;
    case "HIERARCHY":
    case "OUTLINE":
      doc.outlineNodes = emptyOutlineNodes().nodes;
      break;
    case "MIND_MAP":
      doc.mindMap = emptyMindMap();
      break;
    case "FLOW":
    case "PROCESS_FLOW":
      doc.flow = emptyFlow();
      break;
    case "CORNELL_MIND":
      doc.cornell = { notes: "", cues: "", summary: "" };
      doc.mindMap = emptyMindMap();
      break;
    default:
      break;
  }
}

export interface ConversionResult {
  doc: NoteDocument;
  method: NoteMethod;
  formatId: CoreFormatId;
  preserved: boolean;
  message: string;
}

/** Convert between formats without deleting original fields. */
export function convertDocument(
  doc: NoteDocument,
  targetFormatId: CoreFormatId,
  currentMethod: NoteMethod,
): ConversionResult {
  const fromFormat = resolveActiveFormat(doc, currentMethod);
  if (fromFormat === targetFormatId) {
    const def = getFormatDefinition(targetFormatId);
    return {
      doc,
      method: def.noteMethod,
      formatId: targetFormatId,
      preserved: true,
      message: "Already using this format.",
    };
  }

  const merged = structuredClone(doc) as NoteDocument;
  migrateContent(merged, fromFormat, targetFormatId);
  const applied = applyFormatToDocument(merged, targetFormatId, { preserveContent: true });

  return {
    ...applied,
    formatId: targetFormatId,
    preserved: true,
    message: `Converted from ${getFormatDefinition(fromFormat).label} to ${getFormatDefinition(targetFormatId).label}. Original data kept in other views.`,
  };
}

function migrateContent(
  doc: NoteDocument,
  from: CoreFormatId,
  to: CoreFormatId,
): void {
  const plainText = extractPlainText(doc);

  if (to === "MIND_MAP" && plainText) {
    doc.mindMap = textToMindMap(plainText, doc.mindMap);
  }

  if (to === "OUTLINE" || to === "HIERARCHY") {
    doc.outlineNodes = textToOutlineNodes(plainText, doc.outlineNodes);
    doc.typed = plainText || doc.typed;
  }

  if (to === "TIMELINE" && plainText) {
    doc.timeline = textToTimeline(plainText, doc.timeline);
  }

  if (to === "CONCEPT_DEFINITION" && (doc.qa?.pairs.length || plainText)) {
    doc.concepts = qaOrTextToConcepts(doc.qa, plainText);
  }

  if (to === "QA" && doc.concepts?.items.length) {
    doc.qa = {
      pairs: doc.concepts.items.map((item) => ({
        question: item.term ? `What is ${item.term}?` : "",
        answer: [item.definition, item.example].filter(Boolean).join("\n\n"),
      })),
    };
  }

  if (to === "PROBLEM_SOLUTION" && plainText) {
    doc.problemSolution = {
      items: [
        {
          problem: plainText.split("\n")[0] ?? "",
          approach: "",
          solution: plainText.split("\n").slice(1).join("\n"),
          notes: "",
        },
        ...(doc.problemSolution?.items ?? []).slice(1),
      ],
    };
  }

  if ((to === "TWO_COLUMN" || to === "COMPARISON_MATRIX" || to === "CHARTING") && plainText) {
    doc.twoColumn = textToTwoColumn(plainText, doc.twoColumn);
    if (to === "CHARTING" || to === "COMPARISON_MATRIX") {
      doc.charting = twoColumnToCharting(doc.twoColumn);
    }
  }

  if (to === "CORNELL" && plainText) {
    doc.cornell = {
      notes: plainText,
      cues: doc.cornell?.cues ?? "",
      summary: doc.cornell?.summary ?? "",
    };
  }

  if (to === "FLOW" || to === "PROCESS_FLOW") {
    if (doc.timeline?.events.some((e) => e.title)) {
      doc.flow = timelineToFlow(doc.timeline.events);
    } else if (plainText) {
      doc.flow = textToFlow(plainText, doc.flow);
    }
  }

  if (from === "OUTLINE" && to === "CORNELL" && doc.outlineNodes?.length) {
    doc.cornell = {
      notes: doc.outlineNodes.map((n) => `${"  ".repeat(n.level)}${n.text}`).join("\n"),
      cues: doc.cornell?.cues ?? "",
      summary: doc.cornell?.summary ?? "",
    };
  }

  void from;
}

export function extractPlainText(doc: NoteDocument): string {
  const parts: string[] = [];
  if (doc.typed.trim()) parts.push(doc.typed.trim());
  if (doc.cornell?.notes.trim()) parts.push(doc.cornell.notes.trim());
  if (doc.outlineNodes?.length) {
    parts.push(doc.outlineNodes.map((n) => `${"  ".repeat(n.level)}${n.text}`).join("\n"));
  }
  if (doc.qa?.pairs.length) {
    parts.push(
      doc.qa.pairs
        .map((p) => `${p.question}\n${p.answer}`)
        .filter(Boolean)
        .join("\n\n"),
    );
  }
  if (doc.timeline?.events.length) {
    parts.push(
      doc.timeline.events
        .map((e) => `${e.date} — ${e.title}: ${e.description}`)
        .join("\n"),
    );
  }
  if (doc.concepts?.items.length) {
    parts.push(
      doc.concepts.items
        .map((c) => `${c.term}: ${c.definition}`)
        .join("\n"),
    );
  }
  return parts.join("\n\n");
}

function textToMindMap(text: string, existing?: NoteDocument["mindMap"]) {
  const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
  const base = existing ?? emptyMindMap();
  const root = base.nodes[0] ?? { id: "root", label: "Central idea", x: 280, y: 180 };
  const nodes = [root];
  const edges: Array<{ from: string; to: string }> = [];
  lines.slice(0, 8).forEach((line, index) => {
    const id = `n${index}`;
    const label = line.replace(/^[-*#\d.]+\s*/, "").slice(0, 60);
    nodes.push({
      id,
      label: label || `Idea ${index + 1}`,
      x: 120 + (index % 4) * 140,
      y: 80 + Math.floor(index / 4) * 100,
    });
    edges.push({ from: root.id, to: id });
  });
  return { nodes, edges };
}

function textToOutlineNodes(text: string, existing?: NoteDocument["outlineNodes"]) {
  if (existing?.some((n) => n.text.trim())) return existing;
  const lines = text.split("\n").filter((l) => l.trim());
  if (lines.length === 0) return emptyOutlineNodes().nodes;
  return lines.slice(0, 20).map((line, index) => {
    const level = line.match(/^(\s*)/)?.[1].length
      ? Math.min(3, Math.floor((line.match(/^(\s*)/)?.[1].length ?? 0) / 2))
      : line.match(/^[IVX]+\.|^\d+\./)
        ? 0
        : 1;
    return {
      id: `o${index}`,
      text: line.replace(/^[\s\-*#\d.IVX]+/, "").trim(),
      level,
    };
  });
}

function textToTimeline(text: string, existing?: NoteDocument["timeline"]) {
  const lines = text.split("\n").filter((l) => l.trim());
  if (lines.length === 0) return existing ?? emptyTimeline();
  return {
    events: lines.slice(0, 12).map((line) => {
      const dateMatch = line.match(/^(\d{4}[^—\-:]*)[—\-:]\s*(.*)/);
      if (dateMatch) {
        return { date: dateMatch[1].trim(), title: dateMatch[2].trim(), description: "" };
      }
      return { date: "", title: line.trim(), description: "" };
    }),
  };
}

function qaOrTextToConcepts(qa: NoteDocument["qa"], text: string) {
  if (qa?.pairs.some((p) => p.question || p.answer)) {
    return {
      items: qa.pairs.map((pair) => ({
        term: pair.question.replace(/^what is\s+/i, "").replace(/\?$/, ""),
        definition: pair.answer,
        example: "",
        application: "",
      })),
    };
  }
  const terms = text.split("\n").filter((l) => l.includes(":"));
  if (terms.length) {
    return {
      items: terms.map((line) => {
        const [term, ...rest] = line.split(":");
        return {
          term: term.trim(),
          definition: rest.join(":").trim(),
          example: "",
          application: "",
        };
      }),
    };
  }
  return emptyConcepts();
}

function textToTwoColumn(text: string, existing?: NoteDocument["twoColumn"]) {
  const base = existing ?? emptyTwoColumn();
  const lines = text.split("\n").filter((l) => l.trim());
  const rows = lines.slice(0, 12).map((line) => {
    if (line.includes("|")) {
      const [left, right] = line.split("|");
      return { left: left.trim(), right: (right ?? "").trim() };
    }
    if (line.includes(":")) {
      const [left, ...rest] = line.split(":");
      return { left: left.trim(), right: rest.join(":").trim() };
    }
    return { left: line.trim(), right: "" };
  });
  return { ...base, rows: rows.length ? rows : base.rows };
}

function twoColumnToCharting(twoColumn: NoteDocument["twoColumn"]) {
  if (!twoColumn) return { columns: ["A", "B"], rows: [[""]] };
  return {
    columns: [twoColumn.leftHeader, twoColumn.rightHeader],
    rows: twoColumn.rows.map((row) => [row.left, row.right]),
  };
}

function timelineToFlow(events: NoteDocument["timeline"] extends infer T
  ? T extends { events: infer E }
    ? E
    : never
  : never) {
  const flow = emptyFlow();
  const nodes = events.map((event, index) => ({
    id: `t${index}`,
    label: event.title || event.date || `Step ${index + 1}`,
    x: 80 + index * 160,
    y: 160,
  }));
  const edges = nodes.slice(1).map((node, index) => ({
    from: nodes[index].id,
    to: node.id,
  }));
  return { nodes, edges };
}

function textToFlow(text: string, existing?: NoteDocument["flow"]) {
  const lines = text.split("\n").filter((l) => l.trim()).slice(0, 6);
  if (lines.length < 2) return existing ?? emptyFlow();
  const nodes = lines.map((line, index) => ({
    id: `f${index}`,
    label: line.replace(/^[-*\d.]+\s*/, "").slice(0, 40),
    x: 80 + index * 160,
    y: 160,
  }));
  const edges = nodes.slice(1).map((node, index) => ({
    from: nodes[index].id,
    to: node.id,
  }));
  return { nodes, edges };
}

export function mergeAiRecommendations(
  heuristic: FormatRecommendation[],
  aiFormats: Array<{ formatId: CoreFormatId; reason: string; confidence?: number }>,
): FormatRecommendation[] {
  const map = new Map<string, FormatRecommendation>();
  for (const item of heuristic) {
    map.set(item.formatId, item);
  }
  for (const item of aiFormats) {
    const existing = map.get(item.formatId);
    map.set(item.formatId, {
      formatId: item.formatId,
      confidence: Math.max(existing?.confidence ?? 0, item.confidence ?? 0.75),
      reason: item.reason,
      aiSuggested: true,
    });
  }
  return [...map.values()].sort((a, b) => b.confidence - a.confidence).slice(0, 5);
}

/**
 * Dynamic paper surfaces (line color, spacing, paper color) for Core notes.
 * FreeNotes-adjacent knobs without cloning their product.
 */

import type { CSSProperties } from "react";
import type { PageTemplateId } from "@/lib/core/page-templates";

export const DEFAULT_PAPER_COLOR = "#fffdf9";
export const DEFAULT_LINE_COLOR = "#e7e5e4";
export const DEFAULT_RULING_SPACING = 32;

/** Common paper fills for create / edit (GoodNotes-adjacent, not a clone). */
export const NOTEBOOK_PAPER_COLORS: Array<{ id: string; label: string; hex: string }> = [
  { id: "cream", label: "Cream", hex: "#fffdf9" },
  { id: "white", label: "White", hex: "#ffffff" },
  { id: "yellow", label: "Yellow", hex: "#fef9c3" },
  { id: "soft_gray", label: "Soft gray", hex: "#f5f5f4" },
  { id: "blush", label: "Blush", hex: "#fff1f2" },
  { id: "mint", label: "Mint", hex: "#ecfdf5" },
];

const LAYOUT_ONLY: PageTemplateId[] = [
  "blank",
  "cornell",
  "two_column",
  "three_column",
  "meeting_notes",
  "mckinsey",
];

export function isLayoutOnlyTemplate(id?: PageTemplateId | null): boolean {
  if (!id) return true;
  return LAYOUT_ONLY.includes(id);
}

function ruledBackground(
  paper: string,
  line: string,
  gap: number,
  margin = true,
): string {
  const rule = Math.max(18, Math.min(56, gap));
  const lines = `repeating-linear-gradient(transparent, transparent ${rule - 1}px, ${line} ${rule}px)`;
  if (!margin) return lines;
  return `${lines}, linear-gradient(90deg, transparent 47px, #fda4af99 47px, #fda4af99 49px, transparent 49px)`;
}

function dotBackground(paper: string, line: string, gap: number): string {
  const size = Math.max(14, Math.min(40, gap));
  return `radial-gradient(circle, ${line} 1.15px, transparent 1.15px)`;
}

function graphBackground(line: string, gap: number): string {
  const size = Math.max(16, Math.min(48, gap));
  return `linear-gradient(${line} 1px, transparent 1px), linear-gradient(90deg, ${line} 1px, transparent 1px)`;
}

function staffBackground(paper: string, line: string, gap: number): string {
  // Five-line staff groups with space between staves
  const lineGap = Math.max(8, Math.min(16, Math.round(gap / 3)));
  const stave = lineGap * 4;
  const block = stave + lineGap * 3;
  return [
    `repeating-linear-gradient(
      transparent 0,
      transparent ${lineGap}px,
      ${line} ${lineGap}px,
      ${line} ${lineGap + 1}px,
      transparent ${lineGap + 1}px,
      transparent ${lineGap * 2}px,
      ${line} ${lineGap * 2}px,
      ${line} ${lineGap * 2 + 1}px,
      transparent ${lineGap * 2 + 1}px,
      transparent ${lineGap * 3}px,
      ${line} ${lineGap * 3}px,
      ${line} ${lineGap * 3 + 1}px,
      transparent ${lineGap * 3 + 1}px,
      transparent ${lineGap * 4}px,
      ${line} ${lineGap * 4}px,
      ${line} ${lineGap * 4 + 1}px,
      transparent ${lineGap * 4 + 1}px,
      transparent ${block}px
    )`,
  ].join(",");
}

function withPaperGrain(style: CSSProperties): CSSProperties {
  // Soft fiber as the *last* paint layer so ruling/grid backgroundSize stays intact.
  const grain =
    "radial-gradient(rgba(28,25,23,0.055) 0.6px, transparent 0.85px)";
  const existing = style.backgroundImage;
  const size = style.backgroundSize;
  if (!existing) {
    return {
      ...style,
      backgroundImage: grain,
      backgroundSize: "3.5px 3.5px",
    };
  }
  const layerCount = String(existing).split(/,(?![^(]*\))/).length;
  const sizeForExisting =
    size ??
    Array.from({ length: layerCount }, () => "auto").join(", ");
  return {
    ...style,
    backgroundImage: `${existing}, ${grain}`,
    backgroundSize: `${sizeForExisting}, 3.5px 3.5px`,
  };
}

/**
 * Inline background for the page canvas. Prefer this over static Tailwind
 * paperClass whenever paper/line color or spacing can change.
 */
export function resolvePaperSurfaceStyle(input: {
  templateId?: PageTemplateId | null;
  paperColor?: string | null;
  lineColor?: string | null;
  spacingPx?: number | null;
}): CSSProperties {
  const paper = input.paperColor?.trim() || DEFAULT_PAPER_COLOR;
  const line = input.lineColor?.trim() || DEFAULT_LINE_COLOR;
  const gap = input.spacingPx ?? DEFAULT_RULING_SPACING;
  const id = input.templateId ?? "blank";

  const base: CSSProperties = { backgroundColor: paper };

  switch (id) {
    case "ruled":
    case "college_ruled":
    case "cornell_ruled":
    case "planner_week":
      return withPaperGrain({
        ...base,
        backgroundImage: ruledBackground(
          paper,
          line,
          id === "college_ruled" ? Math.round(gap * 0.85) : gap,
          id !== "cornell_ruled",
        ),
      });
    case "legal_pad":
      return withPaperGrain({
        backgroundColor: paper === DEFAULT_PAPER_COLOR ? "#fef9c3" : paper,
        backgroundImage: ruledBackground(
          paper,
          line === DEFAULT_LINE_COLOR ? "#fde68a" : line,
          gap,
        ),
      });
    case "dot_grid":
      return withPaperGrain({
        ...base,
        backgroundImage: dotBackground(paper, line, gap),
        backgroundSize: `${Math.max(14, Math.min(40, gap))}px ${Math.max(14, Math.min(40, gap))}px`,
      });
    case "graph_grid":
    case "cornell_grid":
      return withPaperGrain({
        ...base,
        backgroundImage: graphBackground(line, gap),
        backgroundSize: `${Math.max(16, Math.min(48, gap))}px ${Math.max(16, Math.min(48, gap))}px`,
      });
    case "isometric":
      return withPaperGrain({
        ...base,
        backgroundImage: `linear-gradient(30deg, ${line}88 1px, transparent 1px), linear-gradient(150deg, ${line}88 1px, transparent 1px), linear-gradient(90deg, ${line}66 1px, transparent 1px)`,
        backgroundSize: `${gap}px ${Math.round(gap * 1.7)}px`,
      });
    case "staff":
      return withPaperGrain({
        ...base,
        backgroundImage: staffBackground(paper, line, gap),
      });
    case "study_board":
      return {
        ...base,
        backgroundImage: `linear-gradient(90deg, ${paper} 0, ${paper} 33%, ${line} 33%, ${line} 34%, ${paper} 34%, ${paper} 66%, ${line} 66%, ${line} 67%, ${paper} 67%)`,
      };
    case "kanban":
      return {
        ...base,
        backgroundImage: `linear-gradient(90deg, ${paper} 0, ${paper} 33%, ${line}22 33%, ${line}22 34%, ${paper} 34%, ${paper} 66%, ${line}22 66%, ${line}22 67%, ${paper} 67%)`,
      };
    default:
      // blank / layout overlays — solid paper with light fiber (overlays draw structure)
      return withPaperGrain(base);
  }
}

/** When true, skip Tailwind paperClass so inline style owns the surface. */
export function usesDynamicPaperStyle(templateId?: PageTemplateId | null): boolean {
  return Boolean(templateId) && !isLayoutOnlyTemplate(templateId);
}

