/** Lookup-only LearningSpace for a course — never creates. */
export async function findExistingLearningSpaceForCourse(
  userId: string,
  courseId: string | null | undefined,
): Promise<{ id: string; subjectDomain: string | null } | null> {
  if (!courseId?.trim()) return null;
  const space = await db.learningSpace.findFirst({
    where: { userId, courseId: courseId.trim() },
    select: { id: true, subjectDomain: true },
  });
  return space;
}

/** Find an owned Concept by normalized title within an optional LearningSpace. */
export async function findOwnedConceptByNormalizedTitle(input: {
  userId: string;
  normalizedTitle: string;
  learningSpaceId?: string | null;
}): Promise<{ id: string; title: string } | null> {
  const where =
    input.learningSpaceId != null
      ? { userId: input.userId, learningSpaceId: input.learningSpaceId }
      : { userId: input.userId };

  const rows = await db.concept.findMany({
    where,
    select: { id: true, title: true },
    take: 200,
  });

  const match = rows.find(
    (row) => normalizeConceptTitle(row.title) === input.normalizedTitle,
  );
  return match ?? null;
}

async function loadOwnedNote(userId: string, noteId: string) {
  const note = await db.note.findFirst({
    where: { id: noteId, userId },
    select: {
      id: true,
      userId: true,
      courseId: true,
      topicId: true,
      materialId: true,
      contentJson: true,
      topic: {
        select: {
          id: true,
          name: true,
          conceptId: true,
          concept: { select: { id: true, title: true, userId: true } },
        },
      },
    },
  });
  if (!note) {
    throw new CoreKnowledgeBridgeError("Note not found.");
  }
  return note;
}

function docFromNote(contentJson: string | null): NoteDocument {
  return parseNoteDocument(contentJson);
}

function extractFromDoc(doc: NoteDocument) {
  return readStudyExtractFromUnknown(doc.metadata?.chapterStudyExtract);
}

function knowledgeFromDoc(doc: NoteDocument): LearningKnowledgeMeta {
  return readLearningKnowledgeMeta(doc.metadata?.learningKnowledge);
}

/**
 * Merge learningKnowledge into NoteDocument metadata without dropping other fields.
 */
export function mergeLearningKnowledgeIntoDocument(
  doc: NoteDocument,
  knowledge: LearningKnowledgeMeta,
): NoteDocument {
  return {
    ...doc,
    metadata: {
      ...(doc.metadata ?? {}),
      learningKnowledge: knowledge,
    },
  };
}

async function enrichCandidatesWithExistingConcepts(input: {
  userId: string;
  learningSpaceId: string | null;
  candidates: KnowledgeConceptCandidate[];
  linkedIds: string[];
}): Promise<KnowledgeConceptCandidate[]> {
  const linked = new Set(input.linkedIds);
  const enriched: KnowledgeConceptCandidate[] = [];

  for (const candidate of input.candidates) {
    if (candidate.status === "rejected") {
      enriched.push(candidate);
      continue;
    }

    let existingConceptId = candidate.existingConceptId ?? null;
    if (!existingConceptId) {
      const found = await findOwnedConceptByNormalizedTitle({
        userId: input.userId,
        normalizedTitle: candidate.normalizedTitle,
        learningSpaceId: input.learningSpaceId,
      });
      existingConceptId = found?.id ?? null;
    } else {
      // Verify ownership
      const owned = await db.concept.findFirst({
        where: { id: existingConceptId, userId: input.userId },
        select: { id: true },
      });
      if (!owned) existingConceptId = null;
    }

    let status: KnowledgeConceptCandidate["status"] = candidate.status;
    if (existingConceptId && linked.has(existingConceptId)) {
      status = "linked";
    } else if (existingConceptId) {
      status = "existing";
    } else {
      status = "proposed";
    }

    enriched.push({
      ...candidate,
      existingConceptId,
      status,
    });
  }

  return enriched;
}

export interface CoreKnowledgePreviewResult {
  enabled: boolean;
  noteId: string;
  learningSpaceId: string | null;
  hasStudyExtract: boolean;
  linkedConceptIds: string[];
  candidates: KnowledgeConceptCandidate[];
  truncated: boolean;
  totalBeforeCap: number;
}

/** Preview candidates — no Concept creation, no LearningSpace creation. */
export async function previewCoreKnowledgeBridge(input: {
  userId: string;
  noteId: string;
}): Promise<CoreKnowledgePreviewResult> {
  if (!isCoreKnowledgeBridgeEnabled()) {
    return {
      enabled: false,
      noteId: input.noteId,
      learningSpaceId: null,
      hasStudyExtract: false,
      linkedConceptIds: [],
      candidates: [],
      truncated: false,
      totalBeforeCap: 0,
    };
  }

  const note = await loadOwnedNote(input.userId, input.noteId);
  const doc = docFromNote(note.contentJson);
  const knowledge = knowledgeFromDoc(doc);
  const extract = extractFromDoc(doc);
  const space = await findExistingLearningSpaceForCourse(
    input.userId,
    note.courseId,
  );

  const topicConcept =
    note.topic?.concept && note.topic.concept.userId === input.userId
      ? { id: note.topic.concept.id, title: note.topic.concept.title }
      : null;

  const rawCandidates = extractKnowledgeCandidatesFromStudyExtract(extract, {
    topicConcept,
    alreadyLinkedIds: knowledge.linkedConceptIds,
  });

  // Count uncapped for truncation hint (re-run without relying on internal cap by building loosely)
  const uncapped = extractKnowledgeCandidatesFromStudyExtract(extract, {
    topicConcept,
    alreadyLinkedIds: knowledge.linkedConceptIds,
    cap: 100,
  });

  const rejectedKeys = new Set(
    knowledge.candidateConcepts
      .filter((c) => c.status === "rejected")
      .map((c) => c.key),
  );

  const withRejects = rawCandidates.map((c) =>
    rejectedKeys.has(c.key) ? { ...c, status: "rejected" as const } : c,
  );

  const candidates = await enrichCandidatesWithExistingConcepts({
    userId: input.userId,
    learningSpaceId: space?.id ?? null,
    candidates: withRejects,
    linkedIds: knowledge.linkedConceptIds,
  });

  return {
    enabled: true,
    noteId: note.id,
    learningSpaceId: space?.id ?? null,
    hasStudyExtract: Boolean(extract),
    linkedConceptIds: knowledge.linkedConceptIds,
    candidates,
    truncated: uncapped.length > candidates.length,
    totalBeforeCap: uncapped.length,
  };
}

async function persistNoteKnowledge(
  noteId: string,
  contentJson: string | null,
  knowledge: LearningKnowledgeMeta,
): Promise<LearningKnowledgeMeta> {
  const doc = docFromNote(contentJson);
  const nextDoc = mergeLearningKnowledgeIntoDocument(doc, knowledge);
  await db.note.update({
    where: { id: noteId },
    data: { contentJson: JSON.stringify(nextDoc) },
  });
  return knowledge;
}

/** Confirm a candidate: link existing Concept or create one — user-owned only. */
export async function confirmCoreKnowledgeCandidate(input: {
  userId: string;
  noteId: string;
  candidateKey: string;
}): Promise<{
  conceptId: string;
  created: boolean;
  knowledge: LearningKnowledgeMeta;
}> {
  if (!isCoreKnowledgeBridgeEnabled()) {
    throw new CoreKnowledgeBridgeError("Knowledge bridge is disabled.");
  }

  const note = await loadOwnedNote(input.userId, input.noteId);
  const doc = docFromNote(note.contentJson);
  const knowledge = knowledgeFromDoc(doc);
  const preview = await previewCoreKnowledgeBridge(input);
  const candidate = preview.candidates.find((c) => c.key === input.candidateKey);
  if (!candidate || candidate.status === "rejected") {
    throw new CoreKnowledgeBridgeError("Candidate not found.");
  }

  const space = await findExistingLearningSpaceForCourse(
    input.userId,
    note.courseId,
  );

  let conceptId = candidate.existingConceptId ?? null;
  let created = false;

  if (conceptId) {
    const owned = await db.concept.findFirst({
      where: { id: conceptId, userId: input.userId },
      select: { id: true },
    });
    if (!owned) {
      throw new CoreKnowledgeBridgeError("Concept not found.");
    }
  } else {
    const again = await findOwnedConceptByNormalizedTitle({
      userId: input.userId,
      normalizedTitle: candidate.normalizedTitle,
      learningSpaceId: space?.id ?? null,
    });
    if (again) {
      conceptId = again.id;
    } else {
      const concept = await createConcept({
        userId: input.userId,
        title: candidate.title,
        description: candidate.definition ?? null,
        subjectDomain: space?.subjectDomain ?? null,
        learningSpaceId: space?.id ?? null,
      });
      conceptId = concept.id;
      created = true;
    }
  }

  const linkedConceptIds = [
    ...new Set([...knowledge.linkedConceptIds, conceptId]),
  ];

  const candidateConcepts = preview.candidates.map((c) =>
    c.key === candidate.key
      ? {
          ...c,
          existingConceptId: conceptId,
          status: "linked" as const,
        }
      : c,
  );

  const nextKnowledge: LearningKnowledgeMeta = {
    version: 1,
    linkedConceptIds,
    confirmedAt: new Date().toISOString(),
    candidateConcepts,
  };

  await persistNoteKnowledge(note.id, note.contentJson, nextKnowledge);

  return { conceptId, created, knowledge: nextKnowledge };
}

/** Mark a candidate rejected in note metadata (no Concept delete). */
export async function rejectCoreKnowledgeCandidate(input: {
  userId: string;
  noteId: string;
  candidateKey: string;
}): Promise<{ knowledge: LearningKnowledgeMeta }> {
  if (!isCoreKnowledgeBridgeEnabled()) {
    throw new CoreKnowledgeBridgeError("Knowledge bridge is disabled.");
  }

  const note = await loadOwnedNote(input.userId, input.noteId);
  const doc = docFromNote(note.contentJson);
  const knowledge = knowledgeFromDoc(doc);
  const preview = await previewCoreKnowledgeBridge(input);
  const candidate = preview.candidates.find((c) => c.key === input.candidateKey);
  if (!candidate) {
    throw new CoreKnowledgeBridgeError("Candidate not found.");
  }

  const candidateConcepts = preview.candidates.map((c) =>
    c.key === candidate.key ? { ...c, status: "rejected" as const } : c,
  );

  // Keep prior rejected keys not in this preview
  const keys = new Set(candidateConcepts.map((c) => c.key));
  for (const prior of knowledge.candidateConcepts) {
    if (prior.status === "rejected" && !keys.has(prior.key)) {
      candidateConcepts.push(prior);
    }
  }

  const nextKnowledge: LearningKnowledgeMeta = {
    ...knowledge,
    candidateConcepts,
  };

  await persistNoteKnowledge(note.id, note.contentJson, nextKnowledge);
  return { knowledge: nextKnowledge };
}

/**
 * Load confirmed linked Concept IDs from notes for a course/material context.
 * Ownership-validated. Safe when bridge flag is OFF (returns []).
 */
export async function loadLinkedConceptIdsForCoreContext(input: {
  userId: string;
  courseId?: string | null;
  materialId?: string | null;
}): Promise<string[]> {
  if (!isCoreKnowledgeBridgeEnabled()) return [];

  try {
    const notes = await db.note.findMany({
      where: {
        userId: input.userId,
        ...(input.materialId
          ? { materialId: input.materialId }
          : input.courseId
            ? { courseId: input.courseId }
            : {}),
        contentJson: { not: null },
      },
      orderBy: { updatedAt: "desc" },
      take: 12,
      select: { contentJson: true },
    });

    const ids: string[] = [];
    for (const note of notes) {
      const knowledge = knowledgeFromDoc(docFromNote(note.contentJson));
      ids.push(...knowledge.linkedConceptIds);
    }

    const unique = [...new Set(ids)].slice(0, 5);
    if (unique.length === 0) return [];

    const owned = await db.concept.findMany({
      where: { userId: input.userId, id: { in: unique } },
      select: { id: true },
    });
    return owned.map((c) => c.id);
  } catch (error) {
    console.error("loadLinkedConceptIdsForCoreContext failed:", error);
    return [];
  }
}

/**
 * Phase 11 — Dynamic Learning Paths for retrieved/general topics.
 * Canonical Knowledge Library paths remain preferred and untouched.
 * Dynamic paths are session-scoped and never auto-promoted to KL.
 */

import type { TeachingKnowledgeContext } from "@/lib/learning/knowledge/teaching-knowledge-context";
import {
  matchKnowledgeLearningPath,
  resolveTeachingKnowledgeContext,
} from "@/lib/learning/knowledge/teaching-knowledge-context";
import {
  isGeneralTopicConceptId,
  registerGeneralTeachingContext,
} from "@/lib/learning/knowledge/retrieval/general-identity";
import type { KnowledgeSourceKind } from "@/lib/learning/knowledge/retrieval/types";

export type DynamicLearningPathConcept = {
  conceptId: string;
  title: string;
  order: number;
  prerequisites?: string[];
};

export type DynamicLearningPath = {
  id: string;
  title: string;
  source: KnowledgeSourceKind | "retrieved" | "knowledge-library";
  concepts: DynamicLearningPathConcept[];
  currentIndex: number;
  /** True when derived from registered KL path. */
  canonical: boolean;
};

const SESSION_PATHS = new Map<string, DynamicLearningPath>();

/** Reject fabricated IDs that look like KL packs but aren't registered general/KL. */
export function isSafePathConceptId(
  conceptId: string,
  allowedIds: ReadonlySet<string>,
): boolean {
  const id = conceptId.trim();
  if (!id) return false;
  if (allowedIds.has(id)) return true;
  // Never invent bare KL-looking ids outside the allowed set.
  if (isGeneralTopicConceptId(id)) return allowedIds.has(id);
  return false;
}

/**
 * Build a path from TeachingKnowledgeContext.
 * KL learning-path → canonical.
 * general-retrieval → dynamic session path.
 */
export function learningPathFromTeachingContext(
  ctx: TeachingKnowledgeContext,
  options?: { currentConceptId?: string | null },
): DynamicLearningPath | null {
  if (!ctx.concepts.length) return null;

  const klPath = matchKnowledgeLearningPath(ctx.target);
  const fromLibrary = ctx.source === "knowledge-library";
  const canonical =
    fromLibrary &&
    (ctx.resolution === "learning-path" || Boolean(klPath));

  const concepts: DynamicLearningPathConcept[] = ctx.concepts.map((c, i) => ({
    conceptId: c.id,
    title: c.title,
    order: i,
    prerequisites: c.prerequisites,
  }));

  // Validate: every concept id must be in the context (no fabrication).
  const allowed = new Set(ctx.concepts.map((c) => c.id));
  for (const c of concepts) {
    if (!isSafePathConceptId(c.conceptId, allowed)) {
      return null;
    }
  }

  let currentIndex = 0;
  if (options?.currentConceptId) {
    const idx = concepts.findIndex((c) => c.conceptId === options.currentConceptId);
    if (idx >= 0) currentIndex = idx;
  }

  const path: DynamicLearningPath = {
    id:
      ctx.learningPathId ??
      (fromLibrary
        ? klPath?.id ?? `kl:${ctx.pack?.id ?? ctx.primaryConcept?.id ?? "concept"}`
        : `dynamic:${ctx.target.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 60)}`),
    title: ctx.pack?.displayTitle ?? ctx.target,
    source: fromLibrary
      ? "knowledge-library"
      : ctx.knowledgeSourceKind ??
        (ctx.source === "combined"
          ? "combined"
          : ctx.source === "general-ai"
            ? "general-ai"
            : "retrieved"),
    concepts,
    currentIndex,
    canonical: fromLibrary,
  };

  if (!fromLibrary) {
    SESSION_PATHS.set(path.id, path);
    // Keep general registry warm for evidence continuation.
    registerGeneralTeachingContext(ctx, path.id.replace(/^dynamic:/, ""));
  }

  return path;
}

export function getSessionDynamicPath(pathId: string): DynamicLearningPath | null {
  return SESSION_PATHS.get(pathId) ?? null;
}

export function resetDynamicPathsForTests(): void {
  SESSION_PATHS.clear();
}

/** Next validated concept id, or null (never fabricate). */
export function nextConceptOnPath(
  path: DynamicLearningPath,
): string | null {
  const next = path.concepts[path.currentIndex + 1];
  return next?.conceptId ?? null;
}

/**
 * Prefer canonical KL path when the target matches a registered path or KL pack.
 * Dynamic generation must not replace KL.
 */
export function preferCanonicalPathTarget(target: string): boolean {
  if (matchKnowledgeLearningPath(target) != null) return true;
  return resolveTeachingKnowledgeContext(target) != null;
}

/**
 * Phase 4A — Ensure learner-state writes use Prisma when tables are ready.
 * Falls back to in-memory if generate/migrate has not been applied yet.
 */

import {
  createLearnerStateService,
  setLearnerStateStoreForTests,
  type LearnerStateService,
} from "@/lib/learning/learner-state/service";
import { createMemoryLearnerStateStore } from "@/lib/learning/learner-state/store";

let ready: Promise<LearnerStateService> | null = null;

export function ensureLearnerStatePersistence(): Promise<LearnerStateService> {
  if (!ready) {
    ready = (async () => {
      try {
        const { db } = await import("@/lib/db");
        const evidenceDelegate = (
          db as {
            knowledgeConceptEvidence?: {
              findFirst: (args?: unknown) => Promise<unknown>;
            };
          }
        ).knowledgeConceptEvidence;
        if (!evidenceDelegate?.findFirst) {
          return setLearnerStateStoreForTests(createMemoryLearnerStateStore());
        }
        // Probe that the Phase 4A tables exist (migrate/push may not have run).
        await evidenceDelegate.findFirst({ take: 1 });
        const { createPrismaLearnerStateStore } = await import(
          "@/lib/learning/learner-state/prisma-store"
        );
        return setLearnerStateStoreForTests(createPrismaLearnerStateStore());
      } catch {
        // Reset so a later request can retry after migrate.
        ready = null;
        return setLearnerStateStoreForTests(createMemoryLearnerStateStore());
      }
    })();
  }
  return ready;
}

/** Test helper — clear the cached persistence promise. */
export function resetLearnerStatePersistenceCache(): void {
  ready = null;
}

