export type TeachingQualityLayerFlags = {
  definition: boolean;
  plainExplanation: boolean;
  structure: boolean;
  prerequisites: boolean;
  relationships: boolean;
  examples: boolean;
  misconceptions: boolean;
  application: boolean;
  practice: boolean;
  assessment: boolean;
  curriculum: boolean;
};

export type TeachingQualityTrace = {
  request: string;
  learningTarget: {
    topic: string;
    activity: string;
    scope?: string;
    resolution: string;
  };
  teachScope: TeachScope | null;
  conceptIds: string[];
  conceptTitles: string[];
  knowledgeSource: TeachingKnowledgeContext["source"] | "none";
  knowledgeSourceKind?: string;
  resolution: TeachingKnowledgeContext["resolution"] | "none";
  learningPathId?: string;
  assembled: {
    exactConceptIds: string[];
    prerequisiteIds: string[];
    relationshipTargetIds: string[];
    misconceptionCount: number;
    exampleCount: number;
    practiceFormCount: number;
    transferPromptCount: number;
    curriculumMappingCount: number;
  } | null;
  layersInContext: TeachingQualityLayerFlags;
  layersInLesson: TeachingQualityLayerFlags;
  layersInStudio: TeachingQualityLayerFlags;
  promptBlockContainsLibrary: boolean;
  promptBlockIsHonestAboutSource: boolean;
  lesson: SixWorkedLesson | null;
  studioStages: LearningStudioStage[];
  studioMomentCount: number;
  lessonBlob: string;
  orchestrator?: {
    afterIncorrect: KnowledgeOrchestratorDecision["action"];
    afterReady: KnowledgeOrchestratorDecision["action"];
    reteachDiffers: boolean;
  };
  evidenceRecorded: boolean;
  nextConceptId?: string | null;
  limitations: string[];
};

function flagsFromConceptFields(
  conceptIds: string[],
): TeachingQualityLayerFlags {
  const flags: TeachingQualityLayerFlags = {
    definition: false,
    plainExplanation: false,
    structure: false,
    prerequisites: false,
    relationships: false,
    examples: false,
    misconceptions: false,
    application: false,
    practice: false,
    assessment: false,
    curriculum: false,
  };
  for (const id of conceptIds) {
    const hit = findInstructionalConceptById(id);
    if (!hit) continue;
    const c = hit.concept;
    if (c.definition?.trim()) flags.definition = true;
    if (c.explanation?.trim()) flags.plainExplanation = true;
    if (c.breakdown || c.vocabulary?.length || c.representation) {
      flags.structure = true;
    }
    if (c.prerequisites?.length) flags.prerequisites = true;
    if (c.relationships?.length || c.relatedConcepts?.length) {
      flags.relationships = true;
    }
    if (c.example || c.examples?.length || c.workedExamples?.length) {
      flags.examples = true;
    }
    if (
      c.misconception ||
      c.misconceptions?.length ||
      c.misconceptionDetails?.length
    ) {
      flags.misconceptions = true;
    }
    if (c.applications?.length || c.transferPrompts?.length) {
      flags.application = true;
    }
    if (c.practiceForms?.length) flags.practice = true;
    if (c.assessmentForms?.length || c.checkPrompt) flags.assessment = true;
    if (c.curriculumMappings?.length) flags.curriculum = true;
  }
  return flags;
}

function flagsFromLessonBlob(
  blob: string,
  conceptIds: string[],
): TeachingQualityLayerFlags {
  const lower = blob.toLowerCase();
  const ctxFlags = flagsFromConceptFields(conceptIds);
  // Lesson must actually contain signal, not just context having the field.
  const hasDefinition = conceptIds.some((id) => {
    const d = findInstructionalConceptById(id)?.concept.definition;
    return d && blob.includes(d.slice(0, Math.min(40, d.length)));
  });
  const hasMisconception = conceptIds.some((id) => {
    const c = findInstructionalConceptById(id)?.concept;
    const m =
      c?.misconceptionDetails?.[0]?.misconception ??
      c?.misconception ??
      c?.misconceptions?.[0];
    return m && blob.toLowerCase().includes(m.slice(0, 24).toLowerCase());
  });
  const hasExample = conceptIds.some((id) => {
    const c = findInstructionalConceptById(id)?.concept;
    const ex = c?.example ?? c?.examples?.[0];
    return ex && blob.includes(ex.slice(0, Math.min(30, ex.length)));
  });

  return {
    definition: Boolean(hasDefinition) || (ctxFlags.definition && /definition|is a |means /i.test(blob)),
    plainExplanation: blob.length > 120,
    structure: /break|component|part|vocabulary|key terms/i.test(lower),
    prerequisites: /prerequisite|depends|before|leads/i.test(lower),
    relationships: /→|connect|related|prerequisite|leads/i.test(lower),
    examples: Boolean(hasExample) || /example/i.test(lower),
    misconceptions:
      Boolean(hasMisconception) || /misconception|watch for|common mistake|contrast/i.test(lower),
    application: /apply|transfer|use /i.test(lower),
    practice: /practice|recognize|check|apply/i.test(lower),
    assessment: /check|explain|prompt|assess/i.test(lower),
    curriculum: ctxFlags.curriculum && /curriculum|unit|chapter/i.test(lower)
      ? true
      : ctxFlags.curriculum,
  };
}

function flagsFromStudio(
  lesson: SixWorkedLesson | null,
  conceptIds: string[],
): TeachingQualityLayerFlags {
  if (!lesson) {
    return {
      definition: false,
      plainExplanation: false,
      structure: false,
      prerequisites: false,
      relationships: false,
      examples: false,
      misconceptions: false,
      application: false,
      practice: false,
      assessment: false,
      curriculum: false,
    };
  }
  const blob = [
    ...lesson.chunks.map(
      (c) =>
        `${c.title} ${c.explanation} ${c.example ?? ""} ${c.misconception ?? ""} ${c.breakdown ?? ""} ${c.representation ?? ""} ${c.checkPrompt ?? ""}`,
    ),
    ...lesson.practicePrompts.map((p) => `${p.title} ${p.prompt}`),
  ].join("\n");
  const base = flagsFromLessonBlob(blob, conceptIds);
  const roles = new Set(lesson.chunks.map((c) => c.role));
  return {
    ...base,
    structure: base.structure || roles.has("breakdown"),
    relationships: base.relationships || roles.has("visualize"),
    misconceptions: base.misconceptions || roles.has("clarify"),
    application: base.application || roles.has("apply"),
    assessment: base.assessment || roles.has("check"),
    practice: base.practice || lesson.practicePrompts.length > 0,
  };
}

/**
 * Walk Request → Target → Scope → Retrieval → Teaching → Studio → Evidence → Orchestrator.
 * Deterministic KL path (no live AI). Diagnostic only.
 */
export async function runTeachingQualityTrace(
  request: string,
  options?: { userId?: string },
): Promise<TeachingQualityTrace> {
  const limitations: string[] = [];
  const understood = understandLearningTarget(request);
  if (!understood) {
    return {
      request,
      learningTarget: {
        topic: "",
        activity: "teach",
        resolution: "unresolved",
      },
      teachScope: null,
      conceptIds: [],
      conceptTitles: [],
      knowledgeSource: "none",
      resolution: "none",
      assembled: null,
      layersInContext: flagsFromConceptFields([]),
      layersInLesson: flagsFromConceptFields([]),
      layersInStudio: flagsFromConceptFields([]),
      promptBlockContainsLibrary: false,
      promptBlockIsHonestAboutSource: true,
      lesson: null,
      studioStages: [],
      studioMomentCount: 0,
      lessonBlob: "",
      evidenceRecorded: false,
      limitations: ["Could not understand learning target from request"],
    };
  }
  const teachScope = detectTeachScope(understood);

  const ctx = resolveTeachingKnowledgeContext(understood.topic, {
    scope: teachScope,
    activity: understood.activity,
  });

  let conceptIds: string[] = [];
  if (ctx) {
    conceptIds = ctx.concepts.map((c) => c.id);
    if (conceptIds.length === 0 && ctx.primaryConcept) {
      conceptIds = [ctx.primaryConcept.id];
    }
  } else {
    limitations.push("No Knowledge Library teaching context for target");
  }

  const assembled = ctx?.assembled
    ? {
        exactConceptIds: [
          ...(ctx.assembled.targetConcept
            ? [ctx.assembled.targetConcept.id]
            : []),
          ...ctx.assembled.subconcepts.map((c) => c.id),
        ],
        prerequisiteIds: ctx.assembled.prerequisites.map((c) => c.id),
        relationshipTargetIds: ctx.assembled.relationships.map(
          (r) => r.targetConceptId,
        ),
        misconceptionCount: ctx.assembled.misconceptions.length,
        exampleCount: ctx.assembled.examples.length,
        practiceFormCount: ctx.assembled.practiceForms.length,
        transferPromptCount: ctx.assembled.transferPrompts.length,
        curriculumMappingCount: ctx.assembled.curriculumMappings.length,
      }
    : null;

  const layersInContext = flagsFromConceptFields(conceptIds);

  let lesson: SixWorkedLesson | null = null;
  if (ctx) {
    lesson = lessonFromTeachingKnowledgeContext(
      "detailed-explanation",
      understood.topic,
      ctx,
      null,
      { teachScope },
    );
  } else {
    lesson = buildSubjectAwareFallbackLesson(
      "detailed-explanation",
      understood.topic,
    );
  }

  const lessonBlob = lesson
    ? [
        ...lesson.chunks.map(
          (c) =>
            `${c.title}\n${c.explanation}\n${c.example ?? ""}\n${c.misconception ?? ""}\n${c.breakdown ?? ""}\n${c.representation ?? ""}\n${c.checkPrompt ?? ""}`,
        ),
        ...lesson.practicePrompts.map((p) => `${p.title}: ${p.prompt}`),
        lesson.learningFrame,
        lesson.cheatSheet,
      ].join("\n")
    : "";

  const layersInLesson = flagsFromLessonBlob(lessonBlob, conceptIds);
  const layersInStudio = flagsFromStudio(lesson, conceptIds);

  const promptBlock = ctx ? formatKnowledgeLibraryPromptBlock(ctx) : "";
  const promptBlockContainsLibrary = /KNOWLEDGE LIBRARY CONTEXT/i.test(
    promptBlock,
  );
  const promptBlockIsHonestAboutSource =
    !ctx ||
    ctx.source === "knowledge-library" ||
    /SOURCE-AWARE|general-ai|Primary source kind/i.test(promptBlock);

  const moments = lesson
    ? buildInstructionalMoments({
        lesson,
        conceptTitle: ctx?.primaryConcept?.title ?? understood.topic,
        topic: understood.topic,
        neighborTitles: ctx?.concepts.map((c) => c.title),
      })
    : [];
  const studioStages = lesson
    ? lesson.chunks.map((c) => studioStageFromChunk(c))
    : [];

  // Evidence + orchestrator loop (in-memory, not production DB)
  const userId = options?.userId ?? `tq-trace-${Date.now()}`;
  const store = createMemoryLearnerStateStore();
  const service = createLearnerStateService(store);
  let evidenceRecorded = false;
  let afterIncorrect: KnowledgeOrchestratorDecision["action"] = "complete";
  let afterReady: KnowledgeOrchestratorDecision["action"] = "complete";
  let reteachDiffers = false;
  let nextConceptId: string | null | undefined;

  const focusId = conceptIds[0] ?? null;
  if (focusId && ctx?.source === "knowledge-library") {
    const pathIds =
      conceptIds.length > 1
        ? conceptIds
        : assembled?.exactConceptIds?.length
          ? assembled.exactConceptIds
          : conceptIds;

    // Expand context concepts to path when only one was focused
    const pathCtx: TeachingKnowledgeContext = {
      ...ctx,
      concepts:
        pathIds
          .map((id) => findInstructionalConceptById(id)?.concept)
          .filter((c): c is NonNullable<typeof c> => Boolean(c)).length > 0
          ? pathIds
              .map((id) => findInstructionalConceptById(id)?.concept)
              .filter((c): c is NonNullable<typeof c> => Boolean(c))
          : ctx.concepts,
    };

    await service.recordLearningEvidence({
      userId,
      type: "lesson_exposure",
      conceptId: focusId,
      outcome: "completed",
      source: "teaching-quality-trace",
      eventKey: `${userId}:exposure:${focusId}`,
    });
    evidenceRecorded = true;

    await service.recordLearningEvidence({
      userId,
      type: "check_attempt",
      conceptId: focusId,
      outcome: "incorrect",
      source: "teaching-quality-trace",
      eventKey: `${userId}:incorrect:${focusId}`,
    });

    const evidence = await service.listEvidence(userId);
    const state = await service.getLearnerConceptState(userId, focusId);
    const statesMap = new Map<string, typeof state>(
      pathIds.map((id) => [id, id === focusId ? state : null]),
    );
    const incorrectDecision = decideKnowledgeLoop({
      target: understood.topic,
      knowledge: pathCtx,
      evidence,
      statesByConceptId: statesMap,
    });
    afterIncorrect = incorrectDecision.action;

    const reteachLesson = lessonFromTeachingKnowledgeContext(
      "detailed-explanation",
      understood.topic,
      {
        ...ctx,
        concepts: [ctx.primaryConcept ?? ctx.concepts[0]!].filter(Boolean),
      },
      null,
      { reteachEmphasis: true, teachScope: "focused-concept" },
    );
    const reteachBlob = reteachLesson.chunks
      .map((c) => `${c.misconception ?? ""} ${c.explanation}`)
      .join("\n");
    reteachDiffers =
      afterIncorrect === "reteach" &&
      (/misconception|watch for|contrast|common|incorrect/i.test(reteachBlob) ||
        reteachLesson.chunks.some((c) => c.role === "clarify"));

    await service.recordLearningEvidence({
      userId,
      type: "check_attempt",
      conceptId: focusId,
      outcome: "correct",
      source: "teaching-quality-trace",
      eventKey: `${userId}:correct:${focusId}`,
    });
    await service.recordLearningEvidence({
      userId,
      type: "practice_attempt",
      conceptId: focusId,
      outcome: "correct",
      source: "teaching-quality-trace",
      eventKey: `${userId}:practice:${focusId}`,
    });
    await service.recordLearningEvidence({
      userId,
      type: "recall_result",
      conceptId: focusId,
      outcome: "correct",
      source: "teaching-quality-trace",
      eventKey: `${userId}:recall:${focusId}`,
    });

    const evidence2 = await service.listEvidence(userId);
    const statesMap2 = new Map<
      string,
      Awaited<ReturnType<typeof service.getLearnerConceptState>>
    >();
    for (const id of pathIds) {
      statesMap2.set(id, await service.getLearnerConceptState(userId, id));
    }
    const readyDecision = decideKnowledgeLoop({
      target: understood.topic,
      knowledge: pathCtx,
      evidence: evidence2,
      statesByConceptId: statesMap2,
    });
    afterReady = readyDecision.action;
    nextConceptId = readyDecision.nextConceptId ?? readyDecision.conceptId;
  } else if (!focusId) {
    limitations.push("No focus concept for evidence/orchestrator loop");
  }

  return {
    request,
    learningTarget: {
      topic: understood.topic,
      activity: understood.activity,
      scope: understood.scope,
      resolution: understood.resolution,
    },
    teachScope,
    conceptIds,
    conceptTitles: conceptIds.map(
      (id) => findInstructionalConceptById(id)?.concept.title ?? id,
    ),
    knowledgeSource: ctx?.source ?? "none",
    knowledgeSourceKind: ctx?.knowledgeSourceKind,
    resolution: ctx?.resolution ?? "none",
    learningPathId: ctx?.learningPathId,
    assembled,
    layersInContext,
    layersInLesson,
    layersInStudio,
    promptBlockContainsLibrary,
    promptBlockIsHonestAboutSource,
    lesson,
    studioStages,
    studioMomentCount: moments.length,
    lessonBlob,
    orchestrator: focusId
      ? { afterIncorrect, afterReady, reteachDiffers }
      : undefined,
    evidenceRecorded,
    nextConceptId,
    limitations,
  };
}

/** Assert a lesson blob is not shallow generic filler for a domain keyword. */
export function looksLikeGenericFiller(blob: string, domainHint: string): boolean {
  const t = blob.toLowerCase().replace(/\s+/g, " ");
  const hint = domainHint.toLowerCase();
  // Extremely short or only restates the topic name
  if (t.length < 80) return true;
  const fillerPatterns = [
    new RegExp(`${hint} is important because`, "i"),
    new RegExp(`${hint} is a topic that`, "i"),
    /this concept is useful in many situations\.?$/i,
  ];
  if (fillerPatterns.some((re) => re.test(t) && t.length < 220)) return true;
  return false;
}

import {
  fetchMoodleCalendarEvents,
  fetchMoodleCourseAssignments,
  fetchMoodleCourseContents,
  moodleApiRequest,
} from "@/lib/lms/moodle-api";
import type { MoodleCourseContentModule, MoodleCourseContentSection } from "@/lib/lms/moodle-api";
import { normalizeMoodleBaseUrl } from "@/lib/lms/moodle-url";
import {
  fetchMoodlePagesByCourse,
  parseBookChapterFileUrls,
} from "@/lib/lms/moodle-syllabus";

import { fetchPluginFileText, htmlToPlainText, unixToIso } from "./html";
import { extractSyllabusDateItemsFromText } from "./syllabus-dates";
import type { CourseInfoItem, CourseInfoPortal, CourseInfoSection } from "./types";

const SYLLABUS_PATTERN = /\b(syllabus|course outline|course information|course info)\b/i;

interface BookChapter {
  title: string;
  href: string;
  level: number;
  body: string;
}

interface SectionBucket {
  id: string;
  title: string;
  items: CourseInfoItem[];
}

function sectionTitle(id: string): string {
  const titles: Record<string, string> = {
    overview: "Course Overview",
    "important-dates": "Important Dates",
    instructor: "Instructor Information",
    materials: "Materials & Resources",
    grading: "Grading",
    policies: "Course Policies",
    attendance: "Attendance",
    etiquette: "Online Etiquette",
    technology: "Technology Requirements",
    outcomes: "Learning Outcomes",
    assignments: "Assignments & Major Requirements",
    quizzes: "Quizzes & Assessments",
    projects: "Projects & Presentations",
    media: "Podcasts & Media",
    resources: "Course Resources",
    announcements: "Announcements",
    faq: "Q&A / FAQ",
    other: "Other Information",
  };
  return titles[id] ?? "Course Information";
}

function classifyLabel(text: string): string {
  const t = text.toLowerCase();
  if (/important date|course schedule|academic calendar|weekly schedule|week\s+\d+/.test(t)) {
    return "important-dates";
  }
  if (/instructor|professor|office hour|about your/.test(t)) return "instructor";
  if (/grading|grade breakdown|grade scale/.test(t)) return "grading";
  if (/polic|academic integrity|incomplete work|diversity statement|accessibility/.test(t)) {
    return "policies";
  }
  if (/attendance/.test(t)) return "attendance";
  if (/etiquette|netiquette|online conduct/.test(t)) return "etiquette";
  if (/technical|technology|assistance|computer/.test(t)) return "technology";
  if (/material|resource|textbook|required reading/.test(t)) return "materials";
  if (/outcome|objective/.test(t)) return "outcomes";
  if (/faq|frequently asked|q&a/.test(t)) return "faq";
  if (/business plan|project|presentation|portfolio/.test(t)) return "projects";
  if (/podcast|panopto|media|video/.test(t)) return "media";
  if (/quiz|assessment|exam|test/.test(t)) return "quizzes";
  if (/assignment|homework|due/.test(t)) return "assignments";
  return "other";
}

function bucketMap(): Map<string, SectionBucket> {
  return new Map();
}

function addItem(
  buckets: Map<string, SectionBucket>,
  sectionId: string,
  item: CourseInfoItem,
) {
  if (!item.title?.trim() && !item.body?.trim() && !item.date) return;

  const id = sectionId || "other";
  let bucket = buckets.get(id);
  if (!bucket) {
    bucket = { id, title: sectionTitle(id), items: [] };
    buckets.set(id, bucket);
  }

  const duplicate = bucket.items.some(
    (existing) =>
      existing.title === item.title &&
      existing.date === item.date &&
      existing.body === item.body,
  );
  if (!duplicate) {
    bucket.items.push(item);
  }
}

function parseBookStructure(mod: MoodleCourseContentModule): BookChapter[] {
  return parseBookChapterFileUrls(mod).map((chapter) => ({
    title: chapter.title,
    href: "",
    level: 0,
    body: "",
    _fileUrl: chapter.fileUrl,
  })) as Array<BookChapter & { _fileUrl?: string | null }>;
}

async function loadBookChapters(
  token: string,
  mod: MoodleCourseContentModule,
  bookUrl: string | null,
): Promise<BookChapter[]> {
  const raw = parseBookStructure(mod) as Array<BookChapter & { _fileUrl?: string | null }>;
  const chapters: BookChapter[] = [];

  for (const chapter of raw) {
    let body = "";
    if (chapter._fileUrl) {
      body = await fetchPluginFileText(token, chapter._fileUrl);
    }
    chapters.push({
      title: chapter.title,
      href: chapter.href,
      level: chapter.level,
      body: body.slice(0, 4000),
    });
  }

  if (chapters.length === 0 && mod.description) {
    chapters.push({
      title: mod.name,
      href: "",
      level: 0,
      body: htmlToPlainText(mod.description).slice(0, 4000),
    });
  }

  return chapters;
}

function dateDedupeKey(item: CourseInfoItem): string {
  const ref = item.moodleRef;
  if (ref?.eventId) return `event:${ref.eventId}`;
  if (ref?.modname && ref.instance && item.date) {
    return `${ref.modname}:${ref.instance}:${item.date.slice(0, 10)}`;
  }
  return `${item.title}:${item.date ?? ""}`;
}

function mergeDateItems(items: CourseInfoItem[]): CourseInfoItem[] {
  const best = new Map<string, CourseInfoItem>();
  const priority = (item: CourseInfoItem) => {
    if (item.source.type === "moodle_calendar") {
      if (item.title.toLowerCase().includes("close")) return 4;
      if (item.title.toLowerCase().includes("due")) return 4;
      return 2;
    }
    if (item.source.type === "moodle_assignment") return 3;
    return 1;
  };

  for (const item of items) {
    const key = dateDedupeKey(item);
    const existing = best.get(key);
    if (!existing || priority(item) > priority(existing)) {
      best.set(key, item);
    }
  }

  return [...best.values()].sort((a, b) => {
    if (!a.date || !b.date) return 0;
    return a.date.localeCompare(b.date);
  });
}

function modulesFromContents(
  contents: MoodleCourseContentSection[],
): Array<MoodleCourseContentModule & { sectionName: string }> {
  return contents.flatMap((section) =>
    (section.modules ?? []).map((mod) => ({
      ...mod,
      sectionName: section.name ?? `Section ${section.section}`,
    })),
  );
}

export async function buildCourseInfoPortal(input: {
  studyHaulCourseId: string;
  moodleCourseId: number;
  baseUrl: string;
  token: string;
  courseMeta?: {
    fullname?: string;
    shortname?: string;
    category?: string;
    startdate?: number;
    enddate?: number;
    viewurl?: string;
  };
}): Promise<CourseInfoPortal> {
  const root = normalizeMoodleBaseUrl(input.baseUrl);
  const token = input.token.trim();
  const moodleCourseId = input.moodleCourseId;

  const [contents, assignmentList, calendarEvents, pages] = await Promise.all([
    fetchMoodleCourseContents(root, token, moodleCourseId),
    fetchMoodleCourseAssignments(root, token, moodleCourseId),
    fetchMoodleCalendarEvents(root, token, moodleCourseId),
    fetchMoodlePagesByCourse(root, token, moodleCourseId),
  ]);

  let courseMeta = input.courseMeta;
  if (!courseMeta?.fullname) {
    try {
      const enrolled = await moodleApiRequest<{
        courses?: Array<{
          id: number;
          fullname: string;
          shortname?: string;
          startdate?: number;
          enddate?: number;
          viewurl?: string;
          coursecategory?: string;
        }>;
      }>(root, token, "core_course_get_enrolled_courses_by_timeline_classification", {
        classification: "all",
        limit: "50",
        offset: "0",
      });
      const match = enrolled.courses?.find((course) => course.id === moodleCourseId);
      if (match) {
        courseMeta = {
          fullname: match.fullname,
          shortname: match.shortname,
          startdate: match.startdate,
          enddate: match.enddate,
          viewurl: match.viewurl,
          category: match.coursecategory,
        };
      }
    } catch {
      // optional
    }
  }

  const buckets = bucketMap();
  const modules = modulesFromContents(contents);

  for (const section of contents) {
    if (!section.summary?.trim()) continue;
    const text = htmlToPlainText(section.summary);
    if (text.length < 40) continue;
    addItem(buckets, "overview", {
      title: section.name ?? "Course overview",
      body: text.slice(0, 2000),
      kind: "text",
      source: {
        type: "moodle_section",
        label: `Section: ${section.name}`,
      },
    });
  }

  for (const page of pages) {
    const sectionId = classifyLabel(page.name);
    const body = page.intro ? htmlToPlainText(page.intro) : "";
    addItem(buckets, sectionId, {
      title: page.name,
      body: body.slice(0, 3000) || undefined,
      kind: "text",
      source: {
        type: "moodle_page",
        label: page.name,
        url: modules.find((mod) => mod.id === page.coursemodule)?.url ?? undefined,
      },
      moodleRef: { modname: "page", cmid: page.coursemodule, instance: page.id },
    });
  }

  for (const mod of modules) {
    if (mod.modname === "book" && SYLLABUS_PATTERN.test(mod.name)) {
      const chapters = await loadBookChapters(token, mod, mod.url ?? null);
      for (const chapter of chapters) {
        if (!chapter.body && !chapter.title) continue;
        const sectionId = classifyLabel(chapter.title);
        addItem(buckets, sectionId, {
          title: chapter.title,
          body: chapter.body || undefined,
          kind: sectionId === "policies" ? "policy" : "text",
          source: {
            type: "moodle_book",
            label: `${mod.name} → ${chapter.title}`,
            url: mod.url ?? undefined,
          },
          moodleRef: { modname: "book", cmid: mod.id, instance: mod.instance },
        });
      }
      continue;
    }

    if (mod.modname === "folder" && (mod.contents?.length ?? 0) > 0) {
      const sectionId = classifyLabel(mod.name);
      const files = (mod.contents ?? [])
        .filter((item) => item.type === "file" && item.filename)
        .map((item) => item.filename!);
      if (files.length > 0) {
        addItem(buckets, sectionId === "other" ? "resources" : sectionId, {
          title: mod.name,
          body: files.map((file) => `• ${file}`).join("\n"),
          kind: "list",
          source: {
            type: "moodle_folder",
            label: mod.sectionName,
            url: mod.url ?? undefined,
          },
          moodleRef: { modname: "folder", cmid: mod.id, instance: mod.instance },
        });
      }
    }

    if (mod.modname === "forum") {
      const body = mod.description ? htmlToPlainText(mod.description) : undefined;
      addItem(buckets, "announcements", {
        title: mod.name,
        body,
        kind: "text",
        source: {
          type: "moodle_module",
          label: mod.sectionName,
          url: mod.url ?? undefined,
        },
        moodleRef: { modname: "forum", cmid: mod.id, instance: mod.instance },
      });
    }

    if (mod.modname === "quiz") {
      addItem(buckets, "quizzes", {
        title: mod.name,
        kind: "assignment",
        source: {
          type: "moodle_quiz",
          label: mod.sectionName,
          url: mod.url ?? undefined,
        },
        moodleRef: { modname: "quiz", cmid: mod.id, instance: mod.instance },
      });
    }

    if (mod.modname === "panoptosubmission") {
      addItem(buckets, "media", {
        title: mod.name,
        kind: "assignment",
        source: {
          type: "moodle_module",
          label: mod.sectionName,
          url: mod.url ?? undefined,
        },
        moodleRef: { modname: mod.modname, cmid: mod.id, instance: mod.instance },
      });
    }
  }

  const dateItems: CourseInfoItem[] = [];

  for (const event of calendarEvents) {
    const iso = unixToIso(event.timestart);
    if (!iso) continue;

    const eventLabel =
      event.eventtype === "close" || event.eventtype === "due"
        ? event.name.replace(/\s+(closes?|due)$/i, "").trim()
        : event.name;

    dateItems.push({
      title: eventLabel,
      date: iso,
      body:
        event.eventtype === "open"
          ? "Opens"
          : event.eventtype === "close"
            ? "Closes / due"
            : "Due",
      kind: "date",
      source: {
        type: "moodle_calendar",
        label: "Moodle calendar",
      },
      moodleRef: {
        modname: event.modulename ?? undefined,
        instance: event.instance ?? undefined,
        eventId: event.id,
      },
    });
  }

  for (const assignment of assignmentList) {
    const iso = unixToIso(assignment.duedate);
    if (iso) {
      dateItems.push({
        title: assignment.name,
        date: iso,
        body: assignment.grade ? `Worth ${assignment.grade} points` : undefined,
        kind: "date",
        source: {
          type: "moodle_assignment",
          label: "Moodle assignment",
        },
        moodleRef: {
          modname: "assign",
          cmid: assignment.cmid,
          instance: assignment.id,
        },
      });
    }

    addItem(buckets, classifyLabel(assignment.name), {
      title: assignment.name,
      body: assignment.grade ? `Points: ${assignment.grade}` : undefined,
      date: iso,
      kind: "assignment",
      source: {
        type: "moodle_assignment",
        label: "Moodle assignments",
      },
      moodleRef: {
        modname: "assign",
        cmid: assignment.cmid,
        instance: assignment.id,
      },
    });
  }

  const mergedDates = mergeDateItems(dateItems);

  const syllabusYear = courseMeta?.startdate
    ? new Date(unixToIso(courseMeta.startdate) ?? "").getFullYear()
    : new Date().getFullYear();
  const syllabusDates: CourseInfoItem[] = [];
  for (const bucket of buckets.values()) {
    for (const item of bucket.items) {
      if (!item.body?.trim()) continue;
      syllabusDates.push(
        ...extractSyllabusDateItemsFromText(item.body, item.source.label, syllabusYear),
      );
    }
  }

  const allDates = mergeDateItems([...mergedDates, ...syllabusDates]);
  for (const item of allDates) {
    addItem(buckets, "important-dates", item);
  }

  const sections: CourseInfoSection[] = [...buckets.values()]
    .filter((bucket) => bucket.items.length > 0)
    .sort((a, b) => {
      const order = [
        "overview",
        "important-dates",
        "instructor",
        "outcomes",
        "materials",
        "grading",
        "assignments",
        "quizzes",
        "projects",
        "media",
        "policies",
        "attendance",
        "etiquette",
        "technology",
        "resources",
        "announcements",
        "faq",
        "other",
      ];
      return order.indexOf(a.id) - order.indexOf(b.id);
    });

  return {
    courseId: input.studyHaulCourseId,
    moodleCourseId,
    syncedAt: new Date().toISOString(),
    course: {
      name: courseMeta?.fullname ?? `Course ${moodleCourseId}`,
      shortname: courseMeta?.shortname,
      category: courseMeta?.category,
      startDate: unixToIso(courseMeta?.startdate),
      endDate: unixToIso(courseMeta?.enddate),
      moodleUrl: courseMeta?.viewurl ?? `${root}/course/view.php?id=${moodleCourseId}`,
    },
    sections,
  };
}

