    baseUrl,
    token,
    "core_course_get_contents",
    { courseid: String(courseId) },
  );
}

export async function fetchMoodleCourseAssignments(
  baseUrl: string,
  token: string,
  courseId: number,
): Promise<MoodleAssignment[]> {
  const payload = await moodleApiRequest<{
    courses?: Array<{ id: number; assignments?: MoodleAssignment[] }>;
  }>(baseUrl, token, "mod_assign_get_assignments", {
    "courseids[0]": String(courseId),
  });

  return payload.courses?.find((item) => item.id === courseId)?.assignments ?? [];
}

export async function fetchMoodleAssignmentGrade(
  baseUrl: string,
  token: string,
  assignmentId: number,
): Promise<{ grade: number; maxGrade: number } | null> {
  try {
    const gradesPayload = await moodleApiRequest<{
      assignments?: Array<{
        assignmentid: number;
        grades?: Array<{ userid: number; grade: string; grademax: number }>;
      }>;
    }>(baseUrl, token, "mod_assign_get_grades", {
      "assignmentids[0]": String(assignmentId),
    });
    const gradeRow = gradesPayload.assignments
      ?.find((item) => item.assignmentid === assignmentId)
      ?.grades?.[0];
    if (gradeRow?.grade && gradeRow.grade !== "-1") {
      const grade = Number.parseFloat(gradeRow.grade);
      if (Number.isFinite(grade)) {
        return { grade, maxGrade: gradeRow.grademax ?? 100 };
      }
    }
  } catch {
    // optional
  }
  return null;
}

export async function fetchMoodleCalendarEvents(
  baseUrl: string,
  token: string,
  courseId: number,
): Promise<MoodleCalendarEvent[]> {
  const now = Math.floor(Date.now() / 1000);
  const later = now + 120 * 24 * 60 * 60;

  try {
    const payload = await moodleApiRequest<{ events?: MoodleCalendarEvent[] }>(
      baseUrl,
      token,
      "core_calendar_get_calendar_events",
      {
        "events[courseids][0]": String(courseId),
        "options[userevents]": "0",
        "options[siteevents]": "0",
        "options[timestart]": String(now),
        "options[timeend]": String(later),
      },
    );
    return payload.events ?? [];
  } catch {
    return [];
  }
}

/** Calendar quiz/assign/forum close events that are not already in mod_assign. */
export function moodleCalendarEventsToAssignments(
  events: MoodleCalendarEvent[],
): Array<{ name: string; duedate: number; kind: "quiz" | "assignment"; intro?: string }> {
  const bestByKey = new Map<
    string,
    { name: string; duedate: number; kind: "quiz" | "assignment"; intro?: string; score: number }
  >();

  for (const event of events) {
    const modulename = event.modulename ?? "";
    if (modulename !== "quiz" && modulename !== "assign" && modulename !== "forum") {
      continue;
    }

    const kind = modulename === "quiz" ? "quiz" : "assignment";
    const key = `${modulename}:${event.instance ?? event.id}`;
    const eventtype = (event.eventtype ?? "").toLowerCase();
    const name = event.name
      .replace(/\s+(opens|closes|is due)$/i, "")
      .trim();

    let score = 0;
    if (eventtype === "due" || eventtype === "close") score = 3;
    else if (/\bis due\b|\bdue\b/i.test(event.name)) score = 2;
    else if (eventtype === "open") score = 1;

    // Forums only become assignments for due/close (not open-only noise).
    if (modulename === "forum" && score < 2) continue;

    const existing = bestByKey.get(key);
    if (existing && existing.score >= score) continue;

    bestByKey.set(key, {
      name,
      duedate: event.timestart,
      kind,
      intro: event.description,
      score,
    });
  }

  return [...bestByKey.values()].map(({ score: _score, ...item }) => item);
}

import { describe, expect, it } from "vitest";

import {
  isJunkPrompt,
  isJunkQuizTerm,
  quizQuestionsFromSourceText,
} from "@/lib/quizzes/from-source";
import { QUIZ_QUESTION_DEFAULT } from "@/lib/quizzes/limits";

describe("quizQuestionsFromSourceText", () => {
  it("builds quiz items from a Java Welcome program", () => {
    const source = `
public class Welcome {
  public static void main(String[] args) {
    // Display message Welcome to Java! on the console
    System.out.println("Welcome to Java!");
  }
}
`;
    const questions = quizQuestionsFromSourceText(source);
    expect(questions.length).toBeGreaterThanOrEqual(3);
    expect(questions.some((item) => /Welcome/i.test(String(item.correctAnswer)))).toBe(true);
    expect(questions.some((item) => item.type === "MULTIPLE_CHOICE" || item.type === "SHORT_ANSWER")).toBe(
      true,
    );
  });

  it("builds a chapter-style bank from business definitions", () => {
    const source = `
A business is any activity that seeks to provide goods and services to others while operating at a profit.
Profit is the amount of money a business earns above and beyond what it spends.
A loss occurs when a business's expenses are more than its revenues.
Risk is the chance an entrepreneur takes of losing time and money on a business that may not prove profitable.
Stakeholders are all the people who stand to gain or lose by the policies and activities of a business.
Outsourcing means contracting with other companies to do some of the functions of a firm.
Insourcing occurs when foreign companies establish design and production facilities in the United States.
A nonprofit organization is an organization whose goals do not include making a personal profit for its owners.
Standard of living refers to the amount of goods and services people can buy with the money they have.
Quality of life refers to the general well-being of a society in terms of political freedom, safety, and health.
`;
    const questions = quizQuestionsFromSourceText(source, 30);
    expect(questions.length).toBeGreaterThanOrEqual(12);
    expect(questions.some((item) => item.type === "MULTIPLE_CHOICE")).toBe(true);
    expect(
      questions.some(
        (item) => item.type === "SHORT_ANSWER" || item.type === "FILL_IN_BLANK",
      ),
    ).toBe(true);
    expect(questions.every((item) => item.type !== "TRUE_FALSE")).toBe(true);
    expect(questions.some((item) => /business|profit|stakeholder/i.test(item.prompt))).toBe(true);
  });

  it("ignores TOC headings like Sources and Part 1 Business Trends", () => {
    const source = `
Part 1 Business Trends: An overview of the unit
Sources: Nickels et al.
Source: Course pack
A business is any activity that seeks to provide goods and services to others while operating at a profit.
Profit is the amount of money a business earns above and beyond what it spends for salaries and other expenses.
Stakeholders are all the people who stand to gain or lose by the policies and activities of a business.
`;
    const questions = quizQuestionsFromSourceText(source, 20);
    expect(questions.every((item) => !/define:?\s*(sources?|part\s+1)/i.test(item.prompt))).toBe(
      true,
    );
    expect(questions.some((item) => /business|profit|stakeholder/i.test(item.prompt))).toBe(true);
  });
});

describe("isJunkPrompt", () => {
  it("rejects TOC-style and structural prompts", () => {
    expect(isJunkPrompt("Define: Sources")).toBe(true);
    expect(isJunkPrompt("Define: Part 1 Business Trends")).toBe(true);
    expect(isJunkPrompt("What is Sources?")).toBe(true);
    expect(isJunkPrompt("What is a business?")).toBe(false);
    expect(isJunkPrompt("Define profit.")).toBe(false);
  });
});

describe("chapter review quality bar", () => {
  it("defaults to a full ~30 question review size", () => {
    expect(QUIZ_QUESTION_DEFAULT).toBe(30);
  });

  it("keeps MC + write-ins dominant with no true/false junk from heuristics", () => {
    const source = `
A business is any activity that seeks to provide goods and services to others while operating at a profit.
Profit is the amount of money a business earns above and beyond what it spends.
Stakeholders are all the people who stand to gain or lose by the policies and activities of a business.
Outsourcing means contracting with other companies to do some of the functions of a firm.
Risk is the chance an entrepreneur takes of losing time and money on a business that may not prove profitable.
Entrepreneurs are people who risk time and money to start and manage a business.
Factors of production are the resources used to create wealth: land, labor, capital, entrepreneurship, and knowledge.
`;
    const questions = quizQuestionsFromSourceText(source, QUIZ_QUESTION_DEFAULT);
    const mc = questions.filter((item) => item.type === "MULTIPLE_CHOICE").length;
    const writeIns = questions.filter(
      (item) => item.type === "SHORT_ANSWER" || item.type === "FILL_IN_BLANK",
    ).length;
    expect(questions.length).toBeGreaterThanOrEqual(10);
    expect(mc).toBeGreaterThan(0);
    expect(writeIns).toBeGreaterThan(0);
    expect(questions.every((item) => item.type !== "TRUE_FALSE")).toBe(true);
    expect(questions.every((item) => !isJunkPrompt(item.prompt))).toBe(true);
  });
});

import { db } from "@/lib/db";
import { coursePath } from "@/lib/courses";
import { readableCourseCode, readableCourseName, readableCourseTitle } from "@/lib/courses/display-name";
import { hubAssignmentFocusHref, hubCalendarHref } from "@/lib/hub/tabs";
import { buildSixHrefForTopic } from "@/lib/csl/six-recommendations";

import { formatActivityLabel, sessionHref } from "./search-meta";
import {
  extractInkOcrFromNoteJson,
  noteMatchesSearchQuery,
} from "./note-ink-search";

export type SearchResultType =
  | "course"
  | "assignment"
  | "note"
  | "flashcard"
  | "quiz"
  | "material"
  | "session"
  | "event"
  | "topic";

export interface GlobalSearchResult {
  id: string;
  type: SearchResultType;
  title: string;
  subtitle: string;
  href: string;
  /** When set, search UI can offer Core → Six → Lucky shortcuts for this hit. */
  loopCourseId?: string;
  loopTopic?: string;
}

function matches(haystack: string | null | undefined, query: string) {
  return (haystack ?? "").toLowerCase().includes(query);
}

function courseLabel(course?: { title: string; code?: string | null } | null) {
  if (!course) return null;
  return readableCourseTitle(course.title, course.code);
}

export async function searchGlobal(
  userId: string,
  rawQuery: string,
  limit = 20,
): Promise<GlobalSearchResult[]> {
  const query = rawQuery.trim().toLowerCase();
  if (query.length < 2) return [];

  const [courses, assignments, notes, flashcards, quizzes, materials, sessions, events, topics] =
    await Promise.all([
    db.course.findMany({
      where: { userId },
      select: { id: true, title: true, code: true, instructor: true },
      take: 40,
    }),
    db.assignment.findMany({
      where: { course: { userId } },
      include: { course: { select: { title: true, code: true } } },
      orderBy: { dueDate: "asc" },
      take: 60,
    }),
    db.note.findMany({
      where: { userId },
      include: { course: { select: { id: true, title: true, code: true } } },
      orderBy: { updatedAt: "desc" },
      take: 60,
    }),
    db.flashcard.findMany({
      where: { userId },
      include: { topic: { include: { course: { select: { title: true, code: true } } } } },
      take: 80,
    }),
    db.quiz.findMany({
      where: { userId },
      include: { course: { select: { id: true, title: true, code: true } } },
      orderBy: { updatedAt: "desc" },
      take: 40,
    }),
    db.courseMaterial.findMany({
      where: { course: { userId } },
      include: { course: { select: { id: true, title: true, code: true } } },
      orderBy: { updatedAt: "desc" },
      take: 60,
    }),
    db.studySession.findMany({
      where: { userId },
      include: {
        course: { select: { title: true, code: true } },
        topic: { select: { name: true } },
      },
      orderBy: { startedAt: "desc" },
      take: 80,
    }),
    db.calendarEvent.findMany({
      where: { userId },
      include: { course: { select: { title: true, code: true } } },
      orderBy: { startAt: "desc" },
      take: 80,
    }),
    db.topic.findMany({
      where: { course: { userId } },
      include: {
        course: { select: { id: true, title: true, code: true } },
        masteries: {
          where: { userId },
          take: 1,
        },
      },
      orderBy: { sortOrder: "asc" },
      take: 80,
    }),
  ]);

  const results: GlobalSearchResult[] = [];

  for (const course of courses) {
    const displayTitle = readableCourseName(course);
    const displayCode = readableCourseCode(course);
    if (
      matches(course.title, query) ||
      matches(course.code, query) ||
      matches(displayTitle, query) ||
      matches(displayCode, query) ||
      matches(course.instructor, query)
    ) {
      results.push({
        id: course.id,
        type: "course",
        title: displayTitle,
        subtitle: displayCode ?? "Course",
        href: coursePath(course.id),
        loopCourseId: course.id,
      });
    }
  }

  for (const assignment of assignments) {
    if (
      matches(assignment.title, query) ||
      matches(assignment.description, query) ||
      matches(assignment.course.title, query) ||
      matches(courseLabel(assignment.course), query)
    ) {
      results.push({
        id: assignment.id,
        type: "assignment",
        title: assignment.title,
        subtitle: courseLabel(assignment.course) ?? assignment.course.title,
        href: hubAssignmentFocusHref(assignment.id),
      });
    }
  }

  for (const note of notes) {
    const { matches: noteHit, fromHandwriting } = noteMatchesSearchQuery(note, query);
    if (noteHit) {
      results.push({
        id: note.id,
        type: "note",
        title: note.title ?? "Untitled note",
        subtitle: fromHandwriting
          ? `${courseLabel(note.course) ?? "Core"} · handwriting`
          : courseLabel(note.course) ?? "Core note",
        href: note.course?.id
          ? `/core?courseId=${note.course.id}&noteId=${note.id}`
          : `/core?noteId=${note.id}`,
        loopCourseId: note.course?.id,
      });
    }
  }

  for (const card of flashcards) {
    if (matches(card.front, query) || matches(card.back, query)) {
      results.push({
        id: card.id,
        type: "flashcard",
        title: card.front,
        subtitle: courseLabel(card.topic.course) ?? card.topic.course.title,
        href: card.topic.courseId
          ? `/flashcards?courseId=${card.topic.courseId}`
          : "/flashcards",
        loopCourseId: card.topic.courseId,
        loopTopic: card.topic.name,
      });
    }
  }

  for (const quiz of quizzes) {
    if (
      matches(quiz.title, query) ||
      matches(quiz.description, query) ||
      matches(quiz.course?.title, query) ||
      matches(courseLabel(quiz.course), query)
    ) {
      results.push({
        id: quiz.id,
        type: "quiz",
        title: quiz.title,
        subtitle: courseLabel(quiz.course) ?? "Quiz",
        href: quiz.course?.id
          ? `/quizzes?courseId=${quiz.course.id}`
          : `/quizzes/${quiz.id}`,
        loopCourseId: quiz.course?.id,
      });
    }
  }

  for (const material of materials) {
    if (
      matches(material.title, query) ||
      matches(material.extractedText, query) ||
      matches(material.type, query) ||
      matches(material.course.title, query) ||
      matches(courseLabel(material.course), query)
    ) {
      results.push({
        id: material.id,
        type: "material",
        title: material.title,
        subtitle: courseLabel(material.course) ?? material.course.title,
        href: `/core?courseId=${material.course.id}&materialId=${material.id}`,
        loopCourseId: material.course.id,
      });
    }
  }

  for (const session of sessions) {
    const activityLabel = formatActivityLabel(session.activityType);
    const dateLabel = session.startedAt.toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
    });
    const context = courseLabel(session.course) ?? session.topic?.name ?? "Study session";

    if (
      matches(activityLabel, query) ||
      matches(session.activityType, query) ||
      matches(session.course?.title, query) ||
      matches(courseLabel(session.course), query) ||
      matches(session.topic?.name, query)
    ) {
      results.push({
        id: session.id,
        type: "session",
        title: `${activityLabel} · ${dateLabel}`,
        subtitle: context,
        href: sessionHref(session.activityType),
      });
    }
  }

  for (const event of events) {
    if (
      matches(event.title, query) ||
      matches(event.description, query) ||
      matches(event.location, query) ||
      matches(event.course?.title, query) ||
      matches(courseLabel(event.course), query)
    ) {
      results.push({
        id: event.id,
        type: "event",
        title: event.title,
        subtitle: courseLabel(event.course) ?? "Calendar event",
        href: hubCalendarHref({
          date: event.startAt.toISOString().slice(0, 10),
          focus: event.id,
        }),
      });
    }
  }

  for (const topic of topics) {
    if (
      matches(topic.name, query) ||
      matches(topic.description, query) ||
      matches(topic.course.title, query) ||
      matches(courseLabel(topic.course), query)
    ) {
      const mastery = topic.masteries[0];
      results.push({
        id: topic.id,
        type: "topic",
        title: topic.name,
        subtitle: courseLabel(topic.course) ?? topic.course.title,
        href: buildSixHrefForTopic({
          topicId: topic.id,
          topicName: topic.name,
          courseId: topic.course.id,
          proficiency: mastery?.proficiency,
          understanding: mastery?.understanding,
          recall: mastery?.recall,
          application: mastery?.application,
          reviewCount: mastery?.reviewCount,
        }),
        loopCourseId: topic.course.id,
        loopTopic: topic.name,
      });
    }
  }

  const typeOrder: Record<SearchResultType, number> = {
    course: 0,
    assignment: 1,
    event: 2,
    topic: 3,
    note: 4,
    material: 5,
    flashcard: 6,
    quiz: 7,
    session: 8,
  };

  return results
    .sort((a, b) => typeOrder[a.type] - typeOrder[b.type] || a.title.localeCompare(b.title))
    .slice(0, limit);
}

